{"command":"mkdir -p /tmp/probe && cat > /tmp/probe/probe.py << 'PY'
import subprocess, os, struct, hashlib

EXE=os.path.abspath("./executable")
def run(args, inp=None, cwd="/tmp/probe"):
    return subprocess.run([EXE]+args, cwd=cwd, input=inp, capture_output=True)

def hexdump(b):
    for i in range(0,len(b),16):
        chunk=b[i:i+16]
        print(f"{i:04x}: {' '.join(f'{x:02x}' for x in chunk):48} {''.join(chr(x) if 32<=x<127 else '.' for x in chunk)}")

def parse_frame(b):
    print("total",len(b))
    off=0
    while off < len(b):
        if off+4>len(b): print("trunc magic"); break
        magic=b[off:off+4]; print(f"frame at {off} magic {magic.hex()}")
        if magic==b'\x04\x22\x4d\x18':
            flg,bd=b[off+4],b[off+5]
            print(f" FLG {flg:02x} BD {bd:02x}")
            pos=off+6
            if flg & 0x08:
                cs=struct.unpack('<Q', b[pos:pos+8])[0]; print(" contentSize",cs); pos+=8
            if flg & 0x01:
                did=struct.unpack('<I', b[pos:pos+4])[0]; print(" dictID",did); pos+=4
            hc=b[pos]; print(f" HC {hc:02x}"); pos+=1
            while True:
                if pos+4>len(b): print(" trunc block header"); break
                bs=struct.unpack('<I', b[pos:pos+4])[0]; pos+=4
                uncomp = bool(bs>>31); size=bs & 0x7fffffff
                print(f"  block size {size} uncompressed={uncomp} at {pos}")
                if size==0:
                    # endmark
                    break
                print("   data start", b[pos:pos+min(32,size)].hex())
                pos+=size
                if flg & 0x10:
                    print("   block checksum", b[pos:pos+4].hex()); pos+=4
            if flg & 0x04:
                print(" content checksum", b[pos:pos+4].hex()); pos+=4
            off=pos
        elif magic[:2]==b'\x50\x2a' or (0x184D2A50 <= struct.unpack('<I',magic)[0] <= 0x184D2A5F):
            size=struct.unpack('<I', b[off+4:off+8])[0]; print(" skippable size",size); off+=8+size
        elif magic==b'\x02\x21\x4c\x18':
            print(" legacy frame")
            pos=off+4
            while True:
                if pos+4>len(b): break
                bs=struct.unpack('<I', b[pos:pos+4])[0]; print("  legacy block",bs); pos+=4
                if bs==0: break
                pos+=bs
            off=pos
        else:
            print(" unknown magic"); break

# tests
for name, data in [("empty",b""),("1byte",b"a"),("small",b"hello world"),("repeat",b"abcd"*100),("text",open(os.path.abspath("assets/sample.txt.lz4"),"rb").read())]:
    r=run(["-c","-f","-"], inp=data) if name!="text" else None
    if r:
        print("\n===",name,"rc",r.returncode,"err",r.stderr)
        hexdump(r.stdout)
        parse_frame(r.stdout)

