import subprocess, os, struct
EXE=os.path.abspath("./executable")
def run(args, inp=None, cwd="/tmp/probe"):
    return subprocess.run([EXE]+args, cwd=cwd, input=inp, capture_output=True)
def bd(b): return b[5] if len(b)>5 else None
for size in [100,70000,300000,2000000]:
    data=b"abc"* (size//3+1)
    data=data[:size]
    open("/tmp/probe/s.bin","wb").write(data)
    for B in ["-B4","-B5","-B6","-B7","-B1024","-B100000","-B500000"]:
        r=run(["-c","-f",B,"s.bin"])
        print(f"size={size} {B} BD={bd(r.stdout):02x} err={r.stderr.strip()!r} total={len(r.stdout)}")
    print()
# Also compressed with --content-size - does BD determined by content size?
for size in [100,70000,300000]:
    data=(b"xyz"* (size//3+1))[:size]
    r=run(["-c","-f","--content-size","-B7","-"], inp=data)
    print("content-size stdin",size, f"{bd(r.stdout):02x}", r.stdout[4])
PY"}

