    clean(); open(tmp+"/a.bin","wb").write(b"x"*size)
    r=run(["-l","a.bin","a.out"]); print("legacy",size,r.stderr.split(b'\r'))
    clean(); open(tmp+"/a.bin","wb").write(b"x"*size)
    # decompress legacy to file
    comp=run(["-l","-c","-f","-"],inp=b"x"*size).stdout
    open(tmp+"/a.legacy","wb").write(comp)
    r=run(["-d","a.legacy","out"]); print(" decomp legacy",size,r.stderr.split(b'\r'), "comp len",len(comp), comp.hex())
