import struct
def u32(b,i): return struct.unpack_from('<I',b,i)[0]
def hf(v,log): return ((v*2654435761)&0xffffffff)>>(32-log)

def compress(src,hashLog=12,accel=1,insert_ip_minus_2=True, start_insert=True):
 n=len(src); seqs=[]
 if n<=12:
  return [(n,0,0)]
 table=[0]*(1<<hashLog)
 def put(p):
  if 0<=p<n-3: table[hf(u32(src,p),hashLog)]=p
 def get(p): return table[hf(u32(src,p),hashLog)]
 anchor=0; ip=0
 if start_insert:
  put(0); ip=1
 matchLimit=n-12
 lastRun=n-5
 while True:
  # find match
  forward=ip; step=1; searchNb=accel<<6; cand=0
  while True:
   if forward>matchLimit:
    seqs.append((n-anchor,0,0)); return seqs
   cur=forward
   cand=get(cur)
   forward += step
   step=searchNb>>6; searchNb+=1
   put(cur)
   if cand<cur and cur-cand<=65535 and u32(src,cand)==u32(src,cur):
    ip=cur; break
  # backward extension (low limit is 0)
  while ip>anchor and cand>0 and src[ip-1]==src[cand-1]:
   ip-=1; cand-=1
  litlen=ip-anchor
  # next, code inserts ip-2 before match extension? We'll do after emitting below in variants via flag before mlen? Candidate pos doesn't affect extension.
  if insert_ip_minus_2: put(ip-2)
  mlen=4
  while ip+mlen<lastRun and src[ip+mlen]==src[cand+mlen]:
   mlen+=1
  seqs.append((litlen,ip-cand,mlen))
  anchor=ip+mlen; ip=anchor
  if ip>matchLimit:
   seqs.append((n-anchor,0,0)); return seqs
  if insert_ip_minus_2: put(ip-2)
  # loop to search; note current position will be inserted during search

def show(src,**kw):
 pos=0; res=[]
 for lit,off,ml in compress(src,**kw):
  res.append(f"@{pos} L{lit}" + (f" M{ml}@{off}" if ml else "")); pos+=lit+ml
 return " ".join(res)

if __name__=='__main__':
 src=open("/tmp/sample_text.txt","rb").read()
 for log in [10,11,12,13,14]:
  print(log,show(src,hashLog=log))
