import struct

def u32(b,i): return struct.unpack_from('<I',b,i)[0]
def u64(b,i): return struct.unpack_from('<Q',b,i)[0]

def make_hash(variant,log):
 def h(src,p):
  seq=u64(src,p) if p+8<=len(src) else int.from_bytes(src[p:p+8].ljust(8,b'\0'),'little')
  if variant=='A790': return (((seq<<24)&0xffffffffffffffff)*11400714785074694791 &0xffffffffffffffff) >> (64-log)
  if variant=='A797': return (((seq<<24)&0xffffffffffffffff)*11400714785074694797 &0xffffffffffffffff) >> (64-log)
  if variant=='B889mask': return (((seq & ((1<<40)-1))*889523592379)&0xffffffffffffffff) >> (64-log)
  if variant=='B889shift': return (((seq<<24)&0xffffffffffffffff)*889523592379 &0xffffffffffffffff) >> (64-log)
  if variant=='CprimeMask': return (((seq & ((1<<40)-1))*11400714785074694797)&0xffffffffffffffff) >> (64-log)
  if variant=='D5bytesPrime': 
   # maybe sequence is read_arch >>? 
   return (((seq & ((1<<40)-1))<<24 &0xffffffffffffffff)*11400714785074694797 &0xffffffffffffffff)>>(64-log)
  raise ValueError(variant)
 return h

def compress(src,hashfn,accel=1):
 n=len(src);seqs=[]
 if n<=12:return [(n,0,0)]
 # hash table size inferred max output of hash? pass via closure max? We'll find size by calling? Use dict-like sparse keyed by hash value for testing simulation exact regardless actual size? Actual collisions are because hash returns logbits, so use dict and it simulates table.
 table={}
 def put(p):
  if 0<=p<=n-4:table[hashfn(src,p)]=p
 def get(p):return table.get(hashfn(src,p),0)
 anchor=0;put(0);ip=1;matchLimit=n-12;lastRun=n-5
 while True:
