{"command":"cat > src/xxhash.go << 'EOF'
package main

// xxHash32 implementation (written from the algorithm's public specification
// in terms of its round structure, as needed for the LZ4 frame checksums).

const (
	xxPrime32_1 uint32 = 2654435761
	xxPrime32_2 uint32 = 2246822519
	xxPrime32_3 uint32 = 3266489917
	xxPrime32_4 uint32 = 668265263
	xxPrime32_5 uint32 = 374761393
)

func xxRotl(x uint32, r uint) uint32 { return (x << r) | (x >> (32 - r)) }

func xxRound(acc, inp uint32) uint32 {
	acc += inp * xxPrime32_2
	acc = xxRotl(acc, 13)
	acc *= xxPrime32_1
	return acc
}

func le32(b []byte, i int) uint32 {
	return uint32(b[i]) | uint32(b[i+1])<<8 | uint32(b[i+2])<<16 | uint32(b[i+3])<<24
}
func le16(b []byte, i int) uint16 { return uint16(b[i]) | uint16(b[i+1])<<8 }
func le64(b []byte, i int) uint64 {
	return uint64(le32(b, i)) | uint64(le32(b, i+4))<<32
}

func xxhash32(data []byte, seed uint32) uint32 {
	n := len(data)
	p := 0
	var h uint32
	if n >= 16 {
		v1 := seed + xxPrime32_1 + xxPrime32_2
		v2 := seed + xxPrime32_2
		v3 := seed
		v4 := seed - xxPrime32_1
		for p+16 <= n {
			v1 = xxRound(v1, le32(data, p))
			v2 = xxRound(v2, le32(data, p+4))
			v3 = xxRound(v3, le32(data, p+8))
			v4 = xxRound(v4, le32(data, p+12))
			p += 16
		}
		h = xxRotl(v1, 1) + xxRotl(v2, 7) + xxRotl(v3, 12) + xxRotl(v4, 18)
	} else {
		h = seed + xxPrime32_5
	}
	h += uint32(n)
	for p+4 <= n {
		h += le32(data, p) * xxPrime32_3
		h = xxRotl(h, 17) * xxPrime32_4
		p += 4
	}
	for p < n {
		h += uint32(data[p]) * xxPrime32_5
		h = xxRotl(h, 11) * xxPrime32_1
		p++
	}
	h ^= h >> 15
	h *= xxPrime32_2
	h ^= h >> 13
	h *= xxPrime32_3
	h ^= h >> 16
	return h
}

// Streaming xxHash32. The inputs in this program are fed in whole blocks, so
// the streaming type simply retains a small amount of state in the same
// mathematical form as the one-shot function above. To keep the behaviour
// exact for arbitrary chunk splits it buffers bytes until 16-byte rounds can
// be formed, which is adequate for the block sizes used here.
type xxhStream struct {
	seed  uint32
	total int64
	v1    uint32
	v2    uint32
	v3    uint32
	v4    uint32
	buf   [16]byte
	bufN  int
	big   bool
}

func newXXH(seed uint32) *xxhStream {
	return &xxhStream{seed: seed, v1: seed + xxPrime32_1 + xxPrime32_2, v2: seed + xxPrime32_2, v3: seed, v4: seed - xxPrime32_1}
}

func (s *xxhStream) Write(p []byte) (int, error) {
	n := len(p)
	s.total += int64(n)
	for len(p) > 0 {
		if s.bufN == 0 && len(p) >= 16 {
			s.big = true
			s.v1 = xxRound(s.v1, le32(p, 0))
			s.v2 = xxRound(s.v2, le32(p, 4))
			s.v3 = xxRound(s.v3, le32(p, 8))
			s.v4 = xxRound(s.v4, le32(p, 12))
			p = p[16:]
			continue
		}
		take := 16 - s.bufN
		if take > len(p) {
			take = len(p)
		}
		copy(s.buf[s.bufN:], p[:take])
		s.bufN += take
		p = p[take:]
		if s.bufN == 16 {
			s.big = true
			s.v1 = xxRound(s.v1, le32(s.buf[:], 0))
			s.v2 = xxRound(s.v2, le32(s.buf[:], 4))
			s.v3 = xxRound(s.v3, le32(s.buf[:], 8))
			s.v4 = xxRound(s.v4, le32(s.buf[:], 12))
			s.bufN = 0
		}
	}
	return n, nil
}

func (s *xxhStream) Sum32() uint32 {
	var h uint32
	if s.big {
		h = xxRotl(s.v1, 1) + xxRotl(s.v2, 7) + xxRotl(s.v3, 12) + xxRotl(s.v4, 18)
	} else {
		h = s.seed + xxPrime32_5
	}
	h += uint32(s.total)
	p := s.buf[:s.bufN]
	for len(p) >= 4 {
		h += le32(p, 0) * xxPrime32_3
		h = xxRotl(h, 17) * xxPrime32_4
		p = p[4:]
	}
	for _, c := range p {
		h += uint32(c) * xxPrime32_5
		h = xxRotl(h, 11) * xxPrime32_1
	}
	h ^= h >> 15
	h *= xxPrime32_2
	h ^= h >> 13
	h *= xxPrime32_3
	h ^= h >> 16
	return h
}
