func hash4(seq uint32, log uint) uint32 {
	return (seq * 2654435761) >> (32 - log)
}

// hash5 hashes the first 5 bytes of the little-endian 8-byte sequence.
// Shifting left by 24 discards bytes 5..7 and places the first five
// bytes in the most significant position before the multiply.
func hash5seq(seq uint64, log uint) uint32 {
	const prime5bytes uint64 = 889523592379
	return uint32(((seq << 24) * prime5bytes) >> (64 - log))
}

func readU32(b []byte, i int) uint32 {
	if i < 0 || i+4 > len(b) {
		// The compressor only calls this with valid positions; this
		// defensive path zero-pads like reading past a logical end.
		var tmp [4]byte
		if i < len(b) && i >= 0 {
			copy(tmp[:], b[i:])
		}
		return le32(tmp[:], 0)
	}
	return le32(b, i)
}
func readU64(b []byte, i int) uint64 {
	if i < 0 || i+8 > len(b) {
		var tmp [8]byte
		if i < len(b) && i >= 0 {
			copy(tmp[:], b[i:])
		}
		return le64(tmp[:], 0)
	}
	return le64(b, i)
}

// fastTable is a hash table of positions (indices into a virtual window).
type fastTable struct {
	entries []int32
	log     uint
	hash5   bool
}

func newFastTable(hash5 bool, log uint) *fastTable {
	return &fastTable{entries: make([]int32, 1<<log), log: log, hash5: hash5}
}
func (t *fastTable) hash(src []byte, pos int) uint32 {
	if t.hash5 {
		return hash5seq(readU64(src, pos), t.log)
	}
	return hash4(readU32(src, pos), t.log)
}
func (t *fastTable) put(src []byte, pos int) {
	if pos < 0 || pos+lz4MinMatch > len(src) {
		return
	}
	t.entries[t.hash(src, pos)] = int32(pos)
}
func (t *fastTable) get(src []byte, pos int) int {
	return int(t.entries[t.hash(src, pos)])
}

// shiftPositions adjusts stored positions when the virtual window moves
// forward by delta (old indices decrease by delta).
func (t *fastTable) shiftPositions(delta int) {
	if delta == 0 {
		return
	}
	for i, v := range t.entries {
		nv := int(v) - delta
		if nv < 0 {
			// Entries that fall before the window are kept negative so
			// that candidate validation rejects them.
			t.entries[i] = int32(nv)
		} else {
			t.entries[i] = int32(nv)
		}
