// compressFastGeneric compresses src in the virtual window window, which is
// the concatenation of a history prefix and the current block. Only the
// current block range [blockStart, blockEnd) is emitted. table must have
// been prepared by the caller (fresh, or carried over from a previous
// block in stream mode). startIP is the first position to examine.
func compressFastGeneric(window []byte, blockStart, blockEnd int, table *fastTable, acceleration int, startIP int) []byte {
