		for ip > anchor && candidate > 0 && window[ip-1] == window[candidate-1] {
			ip--
			candidate--
		}
		// Emit one (or more, via the immediate next-match check) sequences.
		for {
			litLen := ip - anchor
			matchLen := lz4MinMatch
			for ip+matchLen < lastRun && window[ip+matchLen] == window[candidate+matchLen] {
