		}
	}
}

// compressBlockFastOneShot compresses a single independent block with no
// dictionary, selecting the hash mode by block size.
func compressBlockFastOneShot(src []byte, acceleration int) []byte {
	if len(src) == 0 {
		return []byte{0}
	}
	var table *fastTable
	if len(src) <= lz4SmallBlockLimit {
		table = newFastTable(false, 13)
	} else {
		table = newFastTable(true, 12)
	}
	table.put(src, 0)
	return compressFastGeneric(src, 0, len(src), table, acceleration, 1)
}

// fastStream is a stateful fast compressor used for block-linked frames
// and dictionary compression. It always uses the 5-byte hash table.
type fastStream struct {
	table *fastTable
	// history holds the retained bytes before the current block
	// (dictionary or tail of previous input), limited logically by the
	// 64KB window during candidate checks.
	history   []byte
	firstUsed bool
	accel     int
}

func newFastStream(acceleration int, dict []byte) *fastStream {
	fs := &fastStream{table: newFastTable(true, 12), accel: acceleration}
	if len(dict) > 0 {
		// The usable dictionary prefix is the last 64KB.
		d := dict
		if len(d) > 65535 {
			// Keep a little more than the window so that positions
			// near the start can still be hashed; candidate distance
			// checks enforce the real window. The reference loader
			// restricts the dictionary to its last 64KB for the
			// purposes of back-references.
			d = d[len(d)-65535:]
		}
		fs.history = append(fs.history[:0], d...)
		fs.loadDict()
		fs.firstUsed = true // dictionary positions already prepared
	}
	return fs
}

// loadDict inserts dictionary positions into the hash table and positions
// the virtual window so history indices are 0..len(history)-1. It is
// called with fs.history already set. The insertion rule mirrors the
// stream dictionary loader: every dictionary position that can start a
// 4-byte sequence is inserted.
func (fs *fastStream) loadDict() {
	// Insert all positions in the dictionary. The final position near
	// the end cannot form a sequence yet because it needs bytes from
	// the upcoming block; those positions are inserted in
	// compressBlock once the window is assembled.
	for p := 0; p+lz4MinMatch <= len(fs.history); p++ {
		fs.table.put(fs.history, p)
	}
}

// compressBlock compresses one block in stream mode, updating history.
func (fs *fastStream) compressBlock(src []byte) []byte {
	hist := fs.history
	if len(hist) > 65535 {
		hist = hist[len(hist)-65535:]
	}
	window := make([]byte, 0, len(hist)+len(src))
	window = append(window, hist...)
	window = append(window, src...)
