		if blockStart != 0 {
			startIP = blockStart
		}
		fs.firstUsed = true
	} else {
		// Continuing a stream (or a dictionary was loaded): the table
		// entries refer to indices in the previous virtual window.
		// They were shifted at the end of the previous block (see
		// below); for a freshly loaded dictionary they already refer
		// to the history prefix of this window. Insert the last
		// positions of the history whose sequences extend into this
