}

// decodeBlock decodes a raw LZ4 block. history is the data immediately
// preceding the block (up to the caller to limit/selection); maxOut is the
// maximum number of bytes the block may produce. It returns the decoded
// bytes for this block only.
func decodeBlock(block, history []byte, maxOut int) ([]byte, error) {
	// Build a virtual buffer: history followed by decoded output.
	// Only the last 64KB+ of history can ever be referenced, but the
	// caller already passes a limited history. We must be able to
	// reference history bytes even when this block's own output is
	// empty, so copy it.
	buf := make([]byte, 0, len(history)+maxOut)
	buf = append(buf, history...)
