	// caller already passes a limited history. We must be able to
	// reference history bytes even when this block's own output is
	// empty, so copy it.
	buf := make([]byte, 0, len(history)+maxOut)
	buf = append(buf, history...)
	start := len(history)
	srcPos := 0
	srcLen := len(block)
	// Track final-literals constraints in the manner of the safe
	// reference decoder: a block that contains any match must end
	// with a literals-only sequence, and matches must not be placed
	// so that they would require reading/writing past the guarded
	// tail region. We enforce the observable rules below.
	hadMatch := false
	lastWasMatch := false
	for {
		if srcPos >= srcLen {
			if srcLen == 0 {
				return nil, errBlockDecompress
			}
			break
		}
		token := block[srcPos]
		srcPos++
		litLen := int(token >> 4)
		if litLen == 15 {
			for {
				if srcPos >= srcLen {
					return nil, errBlockDecompress
				}
				x := int(block[srcPos])
				srcPos++
				litLen += x
				if x != 255 {
					break
				}
				if litLen > maxOut+(1<<20) {
					return nil, errBlockDecompress
				}
			}
		}
		if litLen > srcLen-srcPos {
			return nil, errBlockDecompress
		}
		if (len(buf)-start)+litLen > maxOut {
			return nil, errBlockDecompress
		}
		buf = append(buf, block[srcPos:srcPos+litLen]...)
		srcPos += litLen
		lastWasMatch = false
		if srcPos >= srcLen {
			break
		}
		// Match.
		if srcPos+2 > srcLen {
			return nil, errBlockDecompress
		}
		offset := int(le16(block, srcPos))
		srcPos += 2
		if offset == 0 {
			return nil, errBlockDecompress
		}
		matchLen := int(token & 15)
		if matchLen == 15 {
			for {
				if srcPos >= srcLen {
					return nil, errBlockDecompress
				}
				x := int(block[srcPos])
				srcPos++
				matchLen += x
				if x != 255 {
					break
				}
				if matchLen > maxOut+(1<<20) {
					return nil, errBlockDecompress
				}
			}
		}
		matchLen += lz4MinMatch
		pos := len(buf) - offset
		if pos < 0 {
			return nil, errBlockDecompress
		}
		if (len(buf)-start)+matchLen > maxOut {
			return nil, errBlockDecompress
		}
		hadMatch = true
		lastWasMatch = true
		// Copy with possible overlap.
		for i := 0; i < matchLen; i++ {
			buf = append(buf, buf[pos+i])
		}
	}
	// Validate stream ending rules: the safe decoder rejects a block
	// whose final sequence is a match, and (empirically) blocks in
	// which a short final literals run follows a match too close to
	// the end. The latter is enforced in decodeBlockChecked by the
	// caller if needed; here we enforce the universal rule.
	if hadMatch && lastWasMatch {
		return nil, errBlockDecompress
	}
	_ = hadMatch
	out := make([]byte, len(buf)-start)
	copy(out, buf[start:])
	return out, nil
}
