// byte costs 1 in the output, plus token/extension overhead is accounted
// approximately per sequence. To keep the search tractable on large
// blocks we limit the number of candidate match lengths considered at
// each position to the longest match (and, when favouring decompression
// speed, shorter matches at small offsets are preferred).
func hcCompressOptimal(out *bytes.Buffer, m *hcMatcher, params hcParams) []byte {
	blockStart := m.blockStart
	blockEnd := m.blockEnd
	n := blockEnd
	const inf = int(1 << 60)
	// cost[i] = minimum output bytes to cover window[blockStart:i]
	cost := make([]int, n+1)
