	lastRun := blockEnd - lz4LastLiterals
	// Precompute best match at each position.
	type mo struct{ length, offset int }
	best := make([]mo, n+1)
	for i := blockStart; i <= matchLimit; i++ {
		l, o := m.findBest(i, params.maxSearch, params.targetLen)
		best[i] = mo{l, o}
	}
	seqOverhead := func(litLen, matchLen int) int {
		c := 1
		if litLen >= 15 {
			c += (litLen-15)/255 + 1
		}
		if matchLen > 0 {
			c += 2
			if matchLen-lz4MinMatch >= 15 {
				c += (matchLen-lz4MinMatch-15)/255 + 1
			}
		}
		return c
	}
	// Forward dynamic programming. Literal runs between matches are
	// charged when a sequence is emitted; to keep this simple we
	// charge literals one at a time (1 byte each) and add a small
	// per-sequence overhead when taking a match.
	for i := blockStart; i < blockEnd; i++ {
		if cost[i] == inf {
			continue
		}
		// One literal.
		if c := cost[i] + 1; c < cost[i+1] {
			cost[i+1] = c
			choiceLen[i+1] = 0
			choiceOff[i+1] = 0
		}
		// A match.
		if i <= matchLimit {
			b := best[i]
			if b.length >= lz4MinMatch {
				// Consider the full length and, for decSpeed
				// favouring, penalties that discourage very
				// long matches slightly.
				maxL := b.length
				if i+maxL > lastRun {
					maxL = lastRun - i
				}
				for l := maxL; l >= lz4MinMatch; l-- {
					extra := seqOverhead(0, l)
					if params.favorDec {
						// Penalise each match byte beyond
						// a short run very slightly so the
						// optimiser prefers breaking very
						// long matches when costs tie.
						if l > 8 {
							extra += (l - 8) / 64
						}
					}
					if c := cost[i] + extra; c < cost[i+l] {
						cost[i+l] = c
						choiceLen[i+l] = l
						choiceOff[i+l] = b.offset
					}
					// Only the longest length is generally
					// useful; a couple of shorter variants
					// help near the end.
					if l <= maxL-2 {
						break
					}
				}
			}
		}
	}
	// Backtrack.
	type seg struct{ start, length, offset int }
	var segs []seg
	for i := blockEnd; i > blockStart; {
		l := choiceLen[i]
		if l == 0 {
			i--
		} else {
			segs = append(segs, seg{start: i - l, length: l, offset: choiceOff[i]})
			i -= l
		}
	}
	// Reverse and emit with literal runs between matches, but the
	// final segment must end with literals: ensure the last match
	// does not end after lastRun (it cannot, by construction), and
	// emit the trailing run.
	anchor := blockStart
	for k := len(segs) - 1; k >= 0; k-- {
		s := segs[k]
		emitLiteralRun(out, m.src[anchor:s.start], s.length, s.offset)
		anchor = s.start + s.length
	}
	emitLiteralRun(out, m.src[anchor:blockEnd], 0, 0)
	return out.Bytes()
}

func compressBlockHCOneShot(src []byte, level int, favorDecSpeed bool) []byte {
	if len(src) == 0 {
		return []byte{0}
	}
	return compressBlockHCWindow(src, 0, len(src), level, favorDecSpeed)
}

// hcStream is the HC counterpart of fastStream for block-linked frames
// and dictionary compression.
type hcStream struct {
	history []byte
	level   int
	favor   bool
}

func newHCStream(level int, favor bool, dict []byte) *hcStream {
	s := &hcStream{level: level, favor: favor}
	if len(dict) > 0 {
		d := dict
		if len(d) > 65535 {
			d = d[len(d)-65535:]
		}
		s.history = append(s.history, d...)
	}
	return s
}

func (s *hcStream) compressBlock(src []byte) []byte {
	hist := s.history
	if len(hist) > 65535 {
		hist = hist[len(hist)-65535:]
	}
	window := make([]byte, 0, len(hist)+len(src))
	window = append(window, hist...)
	window = append(window, src...)
	out := compressBlockHCWindow(window, len(hist), len(window), s.level, s.favor)
	keep := 65535
	if len(window) < keep {
		keep = len(window)
	}
	s.history = append(s.history[:0], window[len(window)-keep:]...)
	return out
}
