	out := compressBlockHCWindow(window, len(hist), len(window), s.level, s.favor)
	keep := 65535
	if len(window) < keep {
		keep = len(window)
	}
	s.history = append(s.history[:0], window[len(window)-keep:]...)
	return out
}
