		return hcParams{maxSearch: 16, targetLen: 0}
	case level == 3:
		return hcParams{maxSearch: 32, targetLen: 0}
	case level == 4:
		return hcParams{maxSearch: 64, targetLen: 0}
	case level == 5:
		return hcParams{maxSearch: 128, targetLen: 0}
	case level == 6:
