// searches candidates from most recent to oldest. maxSearch bounds work.
func (m *hcMatcher) findBest(pos int, maxSearch int, targetLen int) (int, int) {
	if pos < m.blockStart || pos+lz4MinMatch > m.blockEnd {
		return 0, 0
	}
	m.insertUpTo(pos)
	h := hcHash(readU32(m.src, pos))
