	bestOff := 0
	maxForward := (m.blockEnd - lz4LastLiterals) - pos
	if maxForward < lz4MinMatch {
		return 0, 0
	}
	searches := 0
	for cand >= 0 && pos-cand <= lz4MaxDistance {
		if searches >= maxSearch && maxSearch > 0 {
			break
		}
		searches++
