// ---------- fatal errors ----------

type fatalError struct {
	code int
	text string // complete bytes to write to stderr (including newline)
}

func (e *fatalError) Error() string { return e.text }

func throw(code int, format string, args ...interface{}) *fatalError {
	msg := fmt.Sprintf(format, args...)
	return &fatalError{code: code, text: fmt.Sprintf("Error %d : %s \n", code, msg)}
}
func throwNoSpace(code int, format string, args ...interface{}) *fatalError {
	msg := fmt.Sprintf(format, args...)
	return &fatalError{code: code, text: fmt.Sprintf("Error %d : %s\n", code, msg)}
}

var errSilentReturn1 = fmt.Errorf("silent return 1")

// ---------- counted writer / block source ----------

type countingWriter struct {
	w io.Writer
	n int64
}

func (c *countingWriter) Write(p []byte) (int, error) {
	n, err := c.w.Write(p)
	c.n += int64(n)
	return n, err
}

type blockSource struct {
	r       io.Reader
	pending []byte
	eof     bool
}

func (s *blockSource) readBlock(max int) ([]byte, error) {
	out := make([]byte, 0, max)
	if len(s.pending) > 0 {
		take := len(s.pending)
		if take > max {
			take = max
		}
		out = append(out, s.pending[:take]...)
		s.pending = s.pending[take:]
	}
	if len(out) < max && !s.eof {
		tmp := make([]byte, max-len(out))
		n, err := io.ReadFull(s.r, tmp)
		if n > 0 {
			out = append(out, tmp[:n]...)
		}
		if err == io.EOF || err == io.ErrUnexpectedEOF {
			s.eof = true
		} else if err != nil {
			return out, err
		}
	}
	return out, nil
}

func (s *blockSource) hasMore() bool {
	if len(s.pending) > 0 {
		return true
	}
	if s.eof {
		return false
	}
	one := make([]byte, 1)
	n, err := io.ReadFull(s.r, one)
	if n > 0 {
		s.pending = append(s.pending, one[:n]...)
		return true
	}
	if err != nil {
		s.eof = true
	}
	return false
}

// ---------- compression settings / block compressor ----------

type compSettings struct {
	level           int // CLI compression level (may be negative)
	favorDecSpeed   bool
	blockSizeID     int // preferred 4..7
	blockLinked     bool
	blockChecksum   bool
	contentChecksum bool
	contentSize     uint64
	hasContentSize  bool
	dict            []byte
	legacy          bool
}

func frameFastAcceleration(level int) int {
	if level < 0 {
		return 1 - level
	}
	return 1
}
func legacyFastAcceleration(level int) int {
	if level < 0 {
		return -level
	}
	return 1
}

// blockCompressor produces compressed blocks for a frame/legacy stream.
type blockCompressor struct {
	settings  compSettings
	streaming bool // use a persistent stream compressor
	fast      *fastStream
	hc        *hcStream
}

func newBlockCompressor(s compSettings, streaming bool) *blockCompressor {
	bc := &blockCompressor{settings: s, streaming: streaming}
	if streaming {
		if s.level >= 2 {
			bc.hc = newHCStream(s.level, s.favorDecSpeed, s.dict)
		} else {
			bc.fast = newFastStream(frameFastAcceleration(s.level), s.dict)
		}
	}
	return bc
}

func (bc *blockCompressor) compressBlock(src []byte) []byte {
	s := bc.settings
	if bc.streaming {
		if bc.hc != nil {
			return bc.hc.compressBlock(src)
		}
		return bc.fast.compressBlock(src)
	}
	// Independent blocks.
	if len(s.dict) > 0 {
		// Each independent block is compressed with the dictionary
		// as its prefix.
		if s.level >= 2 {
			hs := newHCStream(s.level, s.favorDecSpeed, s.dict)
			return hs.compressBlock(src)
		}
		fs := newFastStream(frameFastAcceleration(s.level), s.dict)
		return fs.compressBlock(src)
	}
	if s.level >= 2 {
		return compressBlockHCOneShot(src, s.level, s.favorDecSpeed)
	}
	return compressBlockFastOneShot(src, frameFastAcceleration(s.level))
}

func compressLegacyBlock(src []byte, s compSettings) []byte {
	if s.level >= 3 {
		return compressBlockHCOneShot(src, s.level, s.favorDecSpeed)
	}
	if s.level == 2 {
		// Legacy mode treats level 2 like the fast compressor.
		return compressBlockFastOneShot(src, 1)
	}
	return compressBlockFastOneShot(src, legacyFastAcceleration(s.level))
}

// compressFrameTo writes one LZ4 frame (or a legacy frame) for the whole
// input stream. It returns bytes read and written.
func compressFrameTo(dst io.Writer, src io.Reader, s compSettings) (int64, int64, error) {
	cw := &countingWriter{w: dst}
	if s.legacy {
		return compressLegacyTo(cw, src, s)
	}
	prefMax := blockMaxForID(s.blockSizeID)
	bs := &blockSource{r: src}
	first, err := bs.readBlock(prefMax)
	if err != nil {
		return 0, cw.n, err
	}
	hasMore := bs.hasMore()
	single := !hasMore
	actualID := s.blockSizeID
	actualLinked := s.blockLinked
	if single {
		if len(first) == (4<<20) && prefMax == (4<<20) {
			actualID = 7
			// linked flag stays as requested
		} else {
			actualID = blockIDForSize(len(first), s.blockSizeID)
			actualLinked = false
		}
		if len(first) == 0 {
			actualID = 4
		}
	}
	// Header.
	flg := byte(0x40)
	if !actualLinked {
		flg |= 0x20
	}
	if s.blockChecksum {
		flg |= 0x10
	}
	if s.hasContentSize {
		flg |= 0x08
	}
	if s.contentChecksum {
		flg |= 0x04
	}
	hdrPlain := []byte{flg, byte(actualID << 4)}
	if s.hasContentSize {
		var tmp [8]byte
		binary.LittleEndian.PutUint64(tmp[:], s.contentSize)
		hdrPlain = append(hdrPlain, tmp[:]...)
	}
	hc := byte((xxhash32(hdrPlain, 0) >> 8) & 0xff)
	var magic [4]byte
	binary.LittleEndian.PutUint32(magic[:], frameMagic)
	if _, err := cw.Write(magic[:]); err != nil {
		return 0, cw.n, err
	}
	if _, err := cw.Write(hdrPlain); err != nil {
		return 0, cw.n, err
	}
	if _, err := cw.Write([]byte{hc}); err != nil {
		return 0, cw.n, err
	}
	// Choose block compressor strategy.
	streaming := false
	if !single && (s.blockLinked || len(s.dict) > 0) {
		streaming = s.blockLinked
		// With a dictionary but independent blocks, each block is
		// handled independently with the dictionary (handled inside
		// the non-streaming path).
	}
	if single && len(s.dict) > 0 {
		streaming = true
	}
	bc := newBlockCompressor(s, streaming)
	xx := newXXH(0)
	var totalIn int64
	writeBlock := func(block []byte) error {
		if len(block) == 0 {
			return nil
		}
		xx.Write(block)
		totalIn += int64(len(block))
		compressed := bc.compressBlock(block)
		var hdr uint32
		var data []byte
		if len(compressed) >= len(block) {
			hdr = uint32(len(block)) | 0x80000000
			data = block
		} else {
			hdr = uint32(len(compressed))
			data = compressed
		}
		var bh [4]byte
		binary.LittleEndian.PutUint32(bh[:], hdr)
		if _, err := cw.Write(bh[:]); err != nil {
			return err
		}
		if _, err := cw.Write(data); err != nil {
			return err
		}
		if s.blockChecksum {
			var ck [4]byte
			binary.LittleEndian.PutUint32(ck[:], xxhash32(data, 0))
			if _, err := cw.Write(ck[:]); err != nil {
				return err
			}
		}
		return nil
	}
	if err := writeBlock(first); err != nil {
		return totalIn, cw.n, err
	}
	for hasMore {
		block, err := bs.readBlock(prefMax)
		if err != nil {
			return totalIn, cw.n, err
		}
		if len(block) == 0 {
			break
		}
		if err := writeBlock(block); err != nil {
			return totalIn, cw.n, err
		}
		hasMore = bs.hasMore()
	}
	if _, err := cw.Write([]byte{0, 0, 0, 0}); err != nil {
		return totalIn, cw.n, err
	}
	if s.contentChecksum {
		var ck [4]byte
		binary.LittleEndian.PutUint32(ck[:], xx.Sum32())
		if _, err := cw.Write(ck[:]); err != nil {
			return totalIn, cw.n, err
		}
	}
	return totalIn, cw.n, nil
}

func compressLegacyTo(cw *countingWriter, src io.Reader, s compSettings) (int64, int64, error) {
	var magic [4]byte
	binary.LittleEndian.PutUint32(magic[:], legacyMagic)
	if _, err := cw.Write(magic[:]); err != nil {
		return 0, cw.n, err
	}
	bs := &blockSource{r: src}
	var totalIn int64
	for {
		block, err := bs.readBlock(legacyBlockMaxOut)
		if err != nil {
			return totalIn, cw.n, err
		}
		if len(block) == 0 {
			break
		}
		totalIn += int64(len(block))
		compressed := compressLegacyBlock(block, s)
		var bh [4]byte
		binary.LittleEndian.PutUint32(bh[:], uint32(len(compressed)))
		if _, err := cw.Write(bh[:]); err != nil {
			return totalIn, cw.n, err
		}
		if _, err := cw.Write(compressed); err != nil {
			return totalIn, cw.n, err
		}
	}
	return totalIn, cw.n, nil
}

// Benchmark helper: compress a single raw block with the raw-block level
// mapping used by the benchmark code path.
func benchCompressBlock(src []byte, level int, favor bool, dict []byte) []byte {
	s := compSettings{level: level, favorDecSpeed: favor, dict: dict}
	if len(dict) > 0 {
		bc := newBlockCompressor(s, true)
		return bc.compressBlock(src)
	}
	if level >= 3 {
		return compressBlockHCOneShot(src, level, favor)
	}
	if level == 2 {
		return compressBlockHCOneShot(src, 2, favor)
	}
	return compressBlockFastOneShot(src, frameFastAcceleration(level))
}

// ---------- decompression sink (pending segments / progress) ----------

type decodeSink struct {
	w               io.Writer
	pending         []byte
	total           int64
	firstBurst      int64
	firstBurstKnown bool
	frameSeen       bool // a standard or legacy frame produced a write/flush point
	legacyMode      bool
	writeErr        error
}

func newDecodeSink(w io.Writer) *decodeSink { return &decodeSink{w: w} }

// addStandard adds decoded bytes for a standard frame, flushing every
// 4 MiB.
func (s *decodeSink) addStandard(p []byte) {
	for len(p) > 0 {
		room := progressSegmentSize - len(s.pending)
		take := len(p)
		if take > room {
			take = room
		}
		s.pending = append(s.pending, p[:take]...)
		p = p[take:]
		if len(s.pending) >= progressSegmentSize {
			s.flushPending()
		}
	}
}

func (s *decodeSink) flushPending() {
	if len(s.pending) == 0 {
		return
	}
	if _, err := s.w.Write(s.pending); err != nil && s.writeErr == nil {
		s.writeErr = err
	}
	s.total += int64(len(s.pending))
	if !s.firstBurstKnown {
		s.firstBurst = s.total
		s.firstBurstKnown = true
	}
	s.pending = s.pending[:0]
}

func (s *decodeSink) discardPending() {
	s.pending = s.pending[:0]
}

// writeLegacy writes one legacy block directly.
func (s *decodeSink) writeLegacy(p []byte) {
	s.frameSeen = true
	s.legacyMode = true
	if !s.firstBurstKnown {
		s.firstBurst = int64(len(p))
		s.firstBurstKnown = true
	}
	if _, err := s.w.Write(p); err != nil && s.writeErr == nil {
		s.writeErr = err
	}
	s.total += int64(len(p))
}

// ---------- decompression ----------

func isSkippableMagic(m uint32) bool { return m >= skippableMagicLow && m <= skippableMagicHigh }

type frameDecoder struct {
	r          *bufio.Reader
	sink       *decodeSink
	dict       []byte
	passThrough bool
}

// decompressStream is the top-level stream decoder.
func decompressStream(r *bufio.Reader, sink *decodeSink, dict []byte, passThrough bool) error {
	d := &frameDecoder{r: r, sink: sink, dict: dict, passThrough: passThrough}
	framesProcessed := 0
	for {
		b, _ := r.Peek(4)
		if len(b) == 0 {
			return sink.writeErr
		}
		if len(b) < 4 {
			return throw(40, "Unrecognized header : Magic Number unreadable")
		}
		magic := binary.LittleEndian.Uint32(b)
		if isSkippableMagic(magic) {
			if _, err := r.Discard(4); err != nil {
				return throw(42, "Stream error : skippable size unreadable")
			}
			var szb [4]byte
			if _, err := io.ReadFull(r, szb[:]); err != nil {
				return throw(42, "Stream error : skippable size unreadable")
			}
			size := binary.LittleEndian.Uint32(szb[:])
			if err := skipBytes(r, int64(size)); err != nil {
				return throw(43, "Stream error : cannot skip skippable area")
			}
			framesProcessed++
			continue
		}
		if magic == legacyMagic {
			if _, err := r.Discard(4); err != nil {
				return err
			}
			if err := d.decodeLegacyFrame(); err != nil {
				return err
			}
			framesProcessed++
			continue
		}
		if magic == frameMagic {
			return d.decodeLZ4FFrames()
		}
		// Unknown magic.
		if framesProcessed == 0 {
			if passThrough {
				// Copy the whole stream (including peeked bytes).
				sink.frameSeen = true
				if _, err := io.Copy(sink.w, r); err != nil {
					return err
				}
				// total for passthrough is tracked by caller via
				// counting writer if needed; sink.total is used
				// only for the final "decoded" line, which is not
				// printed in the usual passthrough (stdout) case.
				return sink.writeErr
			}
			return throw(44, "Unrecognized header : file cannot be decoded")
		}
		return errSilentReturn1
	}
}

func skipBytes(r *bufio.Reader, n int64) error {
	for n > 0 {
		chunk := n
		if chunk > 1<<20 {
			chunk = 1 << 20
		}
		skipped, err := r.Discard(int(chunk))
		n -= int64(skipped)
		if err != nil {
			return err
		}
		if skipped == 0 {
			return io.EOF
		}
	}
	return nil
}

func (d *frameDecoder) decodeLegacyFrame() error {
	var history []byte
	first := true
	for {
		b, _ := d.r.Peek(4)
		if len(b) == 0 {
			return nil
		}
		if len(b) < 4 {
			return throw(61, "Error: cannot read block size in Legacy format")
		}
		size := binary.LittleEndian.Uint32(b)
		if size > legacyBlockMaxCompressed {
			// Treat as the start of a following frame.
			return nil
		}
		if _, err := d.r.Discard(4); err != nil {
			return throw(61, "Error: cannot read block size in Legacy format")
		}
		if size == 0 {
			return throw(64, "Decoding Failed ! Corrupted input detected !")
		}
		block := make([]byte, size)
		if _, err := io.ReadFull(d.r, block); err != nil {
			return throw(63, "Read error : cannot access compressed block !")
		}
		out, err := decodeBlock(block, tailBytes(history, 65535), legacyBlockMaxOut)
		if err != nil {
			return throw(64, "Decoding Failed ! Corrupted input detected !")
		}
		if first {
			d.sink.frameSeen = true
			first = false
		}
		d.sink.writeLegacy(out)
		history = appendCapped(history, out, 65535+legacyBlockMaxOut)
	}
}

func tailBytes(b []byte, n int) []byte {
	if len(b) <= n {
		return b
	}
	return b[len(b)-n:]
}
func appendCapped(dst, src []byte, capHint int) []byte {
	dst = append(dst, src...)
	if len(dst) > capHint {
		dst = append([]byte(nil), dst[len(dst)-capHint:]...)
	}
	return dst
}

// decodeLZ4FFrames decodes a sequence of standard/skippable frames with
// LZ4F semantics until clean EOF.
func (d *frameDecoder) decodeLZ4FFrames() error {
	r := d.r
	sink := d.sink
	for {
		b, _ := r.Peek(7)
		if len(b) == 0 {
			return sink.writeErr
		}
		if len(b) < 7 {
			sink.flushPending()
			return throw(26, "LZ4F frame decoding could not complete: invalid frame")
		}
		magic := binary.LittleEndian.Uint32(b)
		if isSkippableMagic(magic) {
			b8, _ := r.Peek(8)
			if len(b8) < 8 {
				sink.flushPending()
				return throw(26, "LZ4F frame decoding could not complete: invalid frame")
			}
			size := binary.LittleEndian.Uint32(b8[4:])
			if _, err := r.Discard(8); err != nil {
				sink.flushPending()
				return throw(26, "LZ4F frame decoding could not complete: invalid frame")
			}
			if err := skipBytes(r, int64(size)); err != nil {
				sink.flushPending()
				return throw(26, "LZ4F frame decoding could not complete: invalid frame")
			}
			continue
		}
		if magic != frameMagic {
			return throw(34, "Decompression error : ERROR_frameType_unknown")
		}
		// Standard frame header.
		if _, err := r.Discard(4); err != nil {
			sink.flushPending()
			return throw(26, "LZ4F frame decoding could not complete: invalid frame")
		}
		flg, err := r.ReadByte()
		if err != nil {
			sink.flushPending()
			return throw(26, "LZ4F frame decoding could not complete: invalid frame")
		}
		bd, err := r.ReadByte()
		if err != nil {
			sink.flushPending()
			return throw(26, "LZ4F frame decoding could not complete: invalid frame")
		}
		hdrPlain := []byte{flg, bd}
		var contentSize uint64
		hasContentSize := flg&0x08 != 0
		if hasContentSize {
			var tmp [8]byte
			if _, err := io.ReadFull(r, tmp[:]); err != nil {
				sink.flushPending()
				return throw(26, "LZ4F frame decoding could not complete: invalid frame")
			}
			contentSize = binary.LittleEndian.Uint64(tmp[:])
			hdrPlain = append(hdrPlain, tmp[:]...)
		}
		if flg&0x01 != 0 {
			var tmp [4]byte
			if _, err := io.ReadFull(r, tmp[:]); err != nil {
				sink.flushPending()
				return throw(26, "LZ4F frame decoding could not complete: invalid frame")
			}
			hdrPlain = append(hdrPlain, tmp[:]...)
		}
		hc, err := r.ReadByte()
		if err != nil {
			sink.flushPending()
			return throw(26, "LZ4F frame decoding could not complete: invalid frame")
		}
		// Header validation (order matches observed error priorities).
		if (flg >> 6) != 1 {
			return throw(34, "Decompression error : ERROR_headerVersion_wrong")
		}
		if flg&0x02 != 0 {
			return throw(34, "Decompression error : ERROR_reservedFlag_set")
		}
		if bd&0x8f != 0 {
			return throw(34, "Decompression error : ERROR_reservedFlag_set")
		}
		blockMaxID := int(bd>>4) & 7
		maxBlockSize := blockMaxForID(blockMaxID)
		if maxBlockSize == 0 {
			return throw(34, "Decompression error : ERROR_maxBlockSize_invalid")
		}
		if byte((xxhash32(hdrPlain, 0)>>8)&0xff) != hc {
			return throw(34, "Decompression error : ERROR_headerChecksum_invalid")
		}
		sink.frameSeen = true
		blockLinked := flg&0x20 == 0
		blockHasChecksum := flg&0x10 != 0
		hasContentChecksum := flg&0x04 != 0
		// Per-frame state.
		xx := newXXH(0)
		var frameTotal uint64
		var window []byte // dictionary + this frame's output (capped logically when used)
		if len(d.dict) > 0 {
			window = append(window, d.dict...)
		}
		firstBlock := true
		frameDone := false
		for !frameDone {
			var bh [4]byte
			if _, err := io.ReadFull(r, bh[:]); err != nil {
				sink.flushPending()
				return throw(26, "LZ4F frame decoding could not complete: invalid frame")
			}
			blockHdr := binary.LittleEndian.Uint32(bh[:])
			raw := blockHdr&0x80000000 != 0
			size := int(blockHdr & 0x7fffffff)
			if size == 0 {
				// EndMark.
				if hasContentSize && frameTotal != contentSize {
					sink.discardPending()
					return throw(34, "Decompression error : ERROR_frameSize_wrong")
				}
				if hasContentChecksum {
					var ck [4]byte
					if _, err := io.ReadFull(r, ck[:]); err != nil {
						sink.flushPending()
						return throw(26, "LZ4F frame decoding could not complete: invalid frame")
					}
					if binary.LittleEndian.Uint32(ck[:]) != xx.Sum32() {
						sink.discardPending()
						return throw(34, "Decompression error : ERROR_contentChecksum_invalid")
					}
				}
				sink.flushPending()
				frameDone = true
				break
			}
			if size > maxBlockSize {
				sink.discardPending()
				return throw(34, "Decompression error : ERROR_maxBlockSize_invalid")
			}
			if raw {
				// Stream the raw block.
				remaining := size
				buf := make([]byte, 32<<10)
				for remaining > 0 {
					take := remaining
					if take > len(buf) {
						take = len(buf)
					}
					n, err := io.ReadFull(r, buf[:take])
					if n > 0 {
						chunk := buf[:n]
						xx.Write(chunk)
						frameTotal += uint64(n)
						window = appendCapped(window, chunk, 65535+maxBlockSize)
						sink.addStandard(chunk)
					}
					if err != nil {
						sink.flushPending()
						return throw(26, "LZ4F frame decoding could not complete: invalid frame")
					}
					remaining -= n
				}
				if blockHasChecksum {
					// For raw blocks the checksum covers the raw
					// bytes; we would need them retained to check.
					// Recompute from the window tail (the raw
					// block is at most maxBlockSize and was just
					// appended; if it is larger than retained
					// window this check is skipped in favour of
					// the content checksum).
					var ck [4]byte
					if _, err := io.ReadFull(r, ck[:]); err != nil {
						sink.flushPending()
						return throw(26, "LZ4F frame decoding could not complete: invalid frame")
					}
					if size <= len(window) {
						data := window[len(window)-size:]
						if binary.LittleEndian.Uint32(ck[:]) != xxhash32(data, 0) {
							sink.discardPending()
							return throw(34, "Decompression error : ERROR_blockChecksum_invalid")
						}
					}
				}
				firstBlock = false
				continue
			}
			// Compressed block: read it fully.
			block := make([]byte, size)
			if _, err := io.ReadFull(r, block); err != nil {
				sink.flushPending()
				return throw(26, "LZ4F frame decoding could not complete: invalid frame")
			}
			if blockHasChecksum {
				var ck [4]byte
				if _, err := io.ReadFull(r, ck[:]); err != nil {
					sink.flushPending()
					return throw(26, "LZ4F frame decoding could not complete: invalid frame")
				}
				if binary.LittleEndian.Uint32(ck[:]) != xxhash32(block, 0) {
					sink.discardPending()
					return throw(34, "Decompression error : ERROR_blockChecksum_invalid")
				}
			}
			var history []byte
			if blockLinked {
				history = tailBytes(window, 65535)
			} else {
				// Independent: dictionary (if any) applies to
				// every block.
				if len(d.dict) > 0 {
					history = tailBytes(d.dict, 65535)
				}
			}
			out, derr := decodeBlock(block, history, maxBlockSize)
			if derr != nil {
				sink.discardPending()
				return throw(34, "Decompression error : ERROR_decompressionFailed")
			}
			xx.Write(out)
			frameTotal += uint64(len(out))
			window = appendCapped(window, out, 65535+maxBlockSize)
			sink.addStandard(out)
			firstBlock = false
			_ = firstBlock
		}
	}
}
