package main

import (
	"io"
	"os"
	"syscall"
)

const sparseSegmentSize = 32768

// sparseWriter writes decompressed output skipping all-zero 32KB segments
// with file seeks. It models the observable segment behaviour: within a
// segment, bytes before the first non-zero byte are skipped, and the rest
// of the segment is written.
type sparseWriter struct {
	f            *os.File
	buf          []byte
	pendingSkip  int64
	ended        bool
}

func newSparseWriter(f *os.File) *sparseWriter {
	return &sparseWriter{f: f}
}

func (s *sparseWriter) Write(p []byte) (int, error) {
	n := len(p)
	for len(p) > 0 {
		room := sparseSegmentSize - len(s.buf)
		take := len(p)
		if take > room {
			take = room
		}
		s.buf = append(s.buf, p[:take]...)
		p = p[take:]
		if len(s.buf) == sparseSegmentSize {
			if err := s.flushSegment(false); err != nil {
				return n, err
			}
		}
	}
	return n, nil
}

func seekErrno(err error) int {
	if pe, ok := err.(*os.PathError); ok {
		err = pe.Err
	}
	if en, ok := err.(syscall.Errno); ok {
		return int(en)
	}
	return 29
}
func seekErrStr(err error) string {
	if pe, ok := err.(*os.PathError); ok {
		err = pe.Err
	}
	if en, ok := err.(syscall.Errno); ok {
		return en.Error()
	}
	return err.Error()
}

// flushSegment processes s.buf. final=true when called from End.
func (s *sparseWriter) flushSegment(final bool) error {
	seg := s.buf
	s.buf = s.buf[:0]
	// Find first non-zero.
	first := -1
	for i, c := range seg {
		if c != 0 {
			first = i
			break
		}
	}
	if first < 0 {
		s.pendingSkip += int64(len(seg))
		return nil
	}
	skip := s.pendingSkip + int64(first)
	// The reference writer issues a seek before writing a non-zero
	// segment even when the skip is zero, which is observable when the
	// destination is a pipe (the seek fails). Mirror that.
	if _, err := s.f.Seek(skip, io.SeekCurrent); err != nil {
		// Error flavour depends on whether the non-zero data lies in
		// a trailing partial 8-byte word of a final small segment.
		tailPartial := final && (len(seg) < 8 || first >= (len(seg)/8)*8)
		if tailPartial {
			return throw(74, "Sparse skip error ; try --no-sparse")
		}
		return &fatalError{code: 72, text: "Error 72 : Sparse skip error(" + itoa(seekErrno(err)) + "): " + capitalizeFirst(seekErrStr(err)) + " ; try --no-sparse \n"}
	}
	s.pendingSkip = 0
	if _, err := s.f.Write(seg[first:]); err != nil {
		return err
	}
	return nil
}

// End flushes the final partial segment and applies any trailing skip.
func (s *sparseWriter) End() error {
	if s.ended {
		return nil
	}
	s.ended = true
	if len(s.buf) > 0 {
		if err := s.flushSegment(true); err != nil {
			return err
		}
	}
	if s.pendingSkip > 0 {
		if _, err := s.f.Seek(s.pendingSkip-1, io.SeekCurrent); err != nil {
			return &fatalError{code: 69, text: "Error 69 : Final skip error (sparse file)\n \n"}
		}
		if _, err := s.f.Write([]byte{0}); err != nil {
			return &fatalError{code: 69, text: "Error 69 : Final skip error (sparse file)\n \n"}
		}
		s.pendingSkip = 0
	}
	return nil
}

func itoa(v int) string {
	if v == 0 {
		return "0"
	}
	neg := v < 0
	if neg {
		v = -v
	}
	var buf [20]byte
	i := len(buf)
	for v > 0 {
		i--
		buf[i] = byte('0' + v%10)
		v /= 10
	}
	if neg {
		i--
		buf[i] = '-'
	}
	return string(buf[i:])
}

func capitalizeFirst(s string) string {
	if s == "" {
		return s
	}
	// C strerror strings used here are capitalised ("Illegal seek").
	// Go errno strings are lower-case; map the common ones.
	switch s {
	case "illegal seek":
		return "Illegal seek"
	}
	if s[0] >= 'a' && s[0] <= 'z' {
		return string(s[0]-'a'+'A') + s[1:]
	}
	return s
}
EOF
