package main

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"
	"runtime"
	"strconv"
	"strings"
	"time"
)

const versionString = "*** lz4 v1.10.0 64-bit multithread, by Yann Collet ***\n"

type opMode int

const (
	modeAuto opMode = iota
	modeCompress
	modeDecompress
	modeTest
	modeBench
	modeList
)

type refKind int

const (
	refUnset refKind = iota
	refStdin
	refStdout
	refNull
	refPath
)

type fileRef struct {
	kind refKind
	path string
}

func (r fileRef) isUnset() bool { return r.kind == refUnset }
func (r fileRef) isStdin() bool { return r.kind == refStdin || (r.kind == refPath && r.path == "stdin") }
func (r fileRef) isStdout() bool {
	return r.kind == refStdout || (r.kind == refPath && r.path == "stdout")
}
func (r fileRef) isNull() bool { return r.kind == refNull || (r.kind == refPath && r.path == "null") }
func (r fileRef) displayName() string {
	switch r.kind {
	case refStdin:
		return "stdin"
	case refStdout:
		return "stdout"
	case refNull:
		return "null"
	default:
		return r.path
	}
}

type cliState struct {
	prog         string
	displayLevel int
	mode         opMode
	multiple     bool
	recursive    bool
	separate     bool // -S (bench: separate files)
	input        fileRef
	output       fileRef
	filenames    []string

	cLevel          int
	benchMaxLevel   int
	benchSeconds    float64
	nbWorkers       int
	blockSize       int // bytes, 0 = unset
	blockLinked     bool
	blockChecksum   bool
	contentChecksum bool
	contentSize     bool
	contentSizeMentioned bool
	favorDecSpeed   bool
	legacy          bool
	dictName        string
	dictSet         bool
	overwrite       bool
	removeSrc       bool
	mainPause       bool
	forceStdout     bool
	sparse          int // 0 off, 1 auto, 2 forced

	startTime   time.Time
	startCPU    time.Duration
	stdinReader *bufio.Reader
}

func (c *cliState) display(level int, format string, args ...interface{}) {
	if c.displayLevel >= level {
		fmt.Fprintf(os.Stderr, format, args...)
	}
}

func usageText(prog string, advanced bool) string {
	var b strings.Builder
	b.WriteString("Usage : \n")
	b.WriteString("      " + prog + " [arg] [input] [output] \n")
	b.WriteString("\n")
	b.WriteString("input   : a filename \n")
	b.WriteString("          with no FILE, or when FILE is - or stdin, read standard input\n")
	b.WriteString("Arguments : \n")
	b.WriteString(" -1     : fast compression (default) \n")
	b.WriteString(" -12    : slowest compression level \n")
	b.WriteString(" -T#    : use # threads for compression (default:0==auto) \n")
	b.WriteString(" -d     : decompression (default for .lz4 extension)\n")
	b.WriteString(" -f     : overwrite output without prompting \n")
	b.WriteString(" -k     : preserve source files(s)  (default) \n")
	b.WriteString("--rm    : remove source file(s) after successful de/compression \n")
	b.WriteString(" -h/-H  : display help/long help and exit \n")
	if !advanced {
		return b.String()
	}
	b.WriteString("\n")
	b.WriteString("Advanced arguments :\n")
	b.WriteString(" -V     : display Version number and exit \n")
	b.WriteString(" -v     : verbose mode \n")
	b.WriteString(" -q     : suppress warnings; specify twice to suppress errors too\n")
	b.WriteString(" -c     : force write to standard output, even if it is the console\n")
	b.WriteString(" -t     : test compressed file integrity\n")
	b.WriteString(" -m     : multiple input files (implies automatic output filenames)\n")
	b.WriteString(" -r     : operate recursively on directories (sets also -m) \n")
	b.WriteString(" -l     : compress using Legacy format (Linux kernel compression)\n")
	b.WriteString(" -z     : force compression \n")
	b.WriteString(" -D FILE: use FILE as dictionary (compression & decompression)\n")
	b.WriteString(" -B#    : cut file into blocks of size # bytes [32+] \n")
	b.WriteString("                     or predefined block size [4-7] (default: 7) \n")
	b.WriteString(" -BI    : Block Independence (default) \n")
	b.WriteString(" -BD    : Block dependency (improves compression ratio) \n")
	b.WriteString(" -BX    : enable block checksum (default:disabled) \n")
	b.WriteString("--no-frame-crc : disable stream checksum (default:enabled) \n")
	b.WriteString("--content-size : compressed frame includes original size (default:not present)\n")
	b.WriteString("--list FILE : lists information about .lz4 files (useful for files compressed with --content-size flag)\n")
	b.WriteString("--[no-]sparse  : sparse mode (default:enabled on file, disabled on stdout)\n")
	b.WriteString("--favor-decSpeed: compressed files decompress faster, but are less compressed \n")
	b.WriteString("--fast[=#]: switch to ultra fast compression level (default: 1)\n")
	b.WriteString("--best  : same as -12\n")
	b.WriteString("Benchmark arguments : \n")
	b.WriteString(" -b#    : benchmark file(s), using # compression level (default : 1) \n")
	b.WriteString(" -e#    : test all compression levels from -bX to # (default : 1)\n")
	b.WriteString(" -i#    : minimum evaluation time in seconds (default : 3s) \n")
	return b.String()
}

func longHelpExtra(prog string) string {
	var b strings.Builder
	b.WriteString("\n")
	b.WriteString("****************************\n")
	b.WriteString("***** Advanced comment *****\n")
	b.WriteString("****************************\n")
	b.WriteString("\n")
	b.WriteString("Which values can [output] have ? \n")
	b.WriteString("---------------------------------\n")
	b.WriteString("[output] : a filename \n")
	b.WriteString("          'stdout', or '-' for standard output (pipe mode)\n")
	b.WriteString("          'null' to discard output (test mode) \n")
	b.WriteString("[output] can be left empty. In this case, it receives the following value :\n")
	b.WriteString("          - if stdout is not the console, then [output] = stdout \n")
	b.WriteString("          - if stdout is console : \n")
	b.WriteString("               + for compression, output to filename.lz4 \n")
	b.WriteString("               + for decompression, output to filename without '.lz4'\n")
	b.WriteString("                    > if input filename has no '.lz4' extension : error \n")
	b.WriteString("\n")
	b.WriteString("Compression levels : \n")
	b.WriteString("---------------------\n")
	b.WriteString("-0  => Default level, identical to -1 \n")
	b.WriteString("-1  => Fast compression \n")
	b.WriteString("-2 .. -12 => High compression; higher number == more compression but slower\n")
	b.WriteString("--best    => Highest available compression level (-12) \n")
	b.WriteString("--fast=#  => Faster compression; higher number == faster but compress less\n")
	b.WriteString("\n")
	b.WriteString("stdin, stdout and the console : \n")
	b.WriteString("--------------------------------\n")
	b.WriteString("To protect the console from binary flooding (bad argument mistake)\n")
	b.WriteString(prog + " will refuse to read from console, or write to console \n")
	b.WriteString("except if '-c' command is specified, to force output to console \n")
	b.WriteString("\n")
	b.WriteString("Simple example :\n")
	b.WriteString("----------------\n")
	b.WriteString("1 : compress 'filename' fast, using default output name 'filename.lz4'\n")
	b.WriteString("          " + prog + " filename\n")
	b.WriteString("\n")
	b.WriteString("Short arguments can be aggregated. For example :\n")
	b.WriteString("----------------------------------\n")
	b.WriteString("2 : compress 'filename' in high compression mode, overwrite output if exists\n")
	b.WriteString("          " + prog + " -9 -f filename \n")
	b.WriteString("    is equivalent to :\n")
	b.WriteString("          " + prog + " -9f filename \n")
	b.WriteString("\n")
	b.WriteString(prog + " can be used in 'pure pipe mode'. For example :\n")
	b.WriteString("-------------------------------------\n")
	b.WriteString("3 : compress data stream from 'generator', send result to 'consumer'\n")
	b.WriteString("          generator | " + prog + " | consumer \n")
	return b.String()
}

// parse terminal actions
const (
	parseOK = iota
	parseExitOK   // help/version (pause applies)
	parseExitFail // bad usage etc. (no pause)
)

func (c *cliState) badUsage() int {
	fmt.Fprintf(os.Stderr, "Incorrect parameters\n")
	fmt.Fprint(os.Stderr, usageText(c.prog, false))
	return parseExitFail
}

func (c *cliState) printHelp(long bool) int {
	fmt.Fprint(os.Stderr, versionString)
	fmt.Fprint(os.Stderr, usageText(c.prog, true))
	if long {
		fmt.Fprint(os.Stderr, longHelpExtra(c.prog))
	}
	return parseExitOK
}

// readUnsigned parses leading decimal digits. It returns the value, the
// number of bytes consumed, and whether any digit was present. Values
// saturate rather than overflow.
func readUnsigned(s string) (uint64, int, bool) {
	i := 0
	var v uint64
	for i < len(s) && s[i] >= '0' && s[i] <= '9' {
		d := uint64(s[i] - '0')
		if v > (1<<63)/10 {
			v = 1 << 62
		} else {
			v = v*10 + d
		}
		i++
	}
	return v, i, i > 0
}

// readSize parses an unsigned with an optional K/M suffix (with optional
// iB/B tail, case-insensitive for the iB part as observed). It returns
// the byte value, the remaining string, and success (a digit was present
// and the suffix, if any, was recognised). If the first character is not
// a digit it returns ok=false with the input untouched.
func readSize(s string) (uint64, string, bool) {
	v, n, ok := readUnsigned(s)
	if !ok {
		return 0, s, false
	}
	rest := s[n:]
	if rest == "" {
		return v, rest, true
	}
	var mult uint64
	switch rest[0] {
	case 'K':
		mult = 1 << 10
	case 'M':
		mult = 1 << 20
	default:
		return v, rest, true
	}
	rest = rest[1:]
	// Optional "iB", "IB" or "B" tail.
	if len(rest) >= 2 && (rest[0] == 'i' || rest[0] == 'I') && rest[1] == 'B' {
		rest = rest[2:]
	} else if len(rest) >= 1 && rest[0] == 'B' {
		rest = rest[1:]
	}
	return v * mult, rest, true
}

func (c *cliState) setMultiple() {
	if !c.multiple {
		c.multiple = true
		c.input = fileRef{kind: refUnset}
	}
}

// parseBlockSizeArg parses the tail of a -B argument (the part after B).
// It returns parseOK or parseExitFail (bad usage).
func (c *cliState) parseBlockSizeArg(rest string) int {
	for rest != "" {
		if rest[0] >= '0' && rest[0] <= '9' {
			// Distinguish a single predefined digit 4..7 (possibly
			// followed by modifiers or a suffix like KB).
			v, remaining, _ := readSize(rest)
			// readSize consumes a K/M suffix; a lone digit 4..7
			// with no suffix and no further digits is a block ID.
			// Detect: original token had exactly one digit before
			// remaining and no suffix was consumed.
			// We can detect a suffix by re-reading plain digits.
			plainV, plainN, _ := readUnsigned(rest)
			_ = plainV
			usedSuffix := !(plainN == len(rest)-len(remaining))
			var size uint64
			if !usedSuffix && plainN == 1 && v >= 4 && v <= 7 {
				size = uint64(blockMaxForID(int(v)))
			} else {
				size = v
				if size > 0 && size < 32 {
					return c.badUsage()
				}
			}
			if size > 0 {
				if size > 4<<20 {
					size = 4 << 20
				}
				c.blockSize = int(size)
				// Announce at parse time if warnings are enabled.
				if c.displayLevel >= 2 {
					if size < 1024 {
						fmt.Fprintf(os.Stderr, "using blocks of size %d bytes \n", size)
					} else {
						fmt.Fprintf(os.Stderr, "using blocks of size %d KB \n", size>>10)
					}
				}
			}
			rest = remaining
			continue
		}
		switch rest[0] {
		case 'D':
			c.blockLinked = true
			rest = rest[1:]
		case 'I':
			c.blockLinked = false
			rest = rest[1:]
		case 'X':
			c.blockChecksum = true
			rest = rest[1:]
		default:
			return c.badUsage()
		}
	}
	return parseOK
}

func (c *cliState) addPositional(arg string) int {
	if c.multiple {
		c.filenames = append(c.filenames, arg)
		return parseOK
	}
	if c.input.isUnset() {
		c.input = fileRef{kind: refPath, path: arg}
		return parseOK
	}
	if c.output.isUnset() {
		c.output = fileRef{kind: refPath, path: arg}
		return parseOK
	}
	fmt.Fprintf(os.Stderr, "Error : %s won't be used ! Do you want multiple input files (-m) ? \n", arg)
	return parseExitFail
}

// parseArgs parses os.Args[1:]. It returns a parse action.
func (c *cliState) parseArgs(argv []string) int {
	parsing := true
	i := 0
	for i < len(argv) {
		arg := argv[i]
		i++
		if parsing && arg == "--" {
			parsing = false
			continue
		}
		if parsing && arg == "-" {
			if c.input.isUnset() {
				c.input = fileRef{kind: refStdin}
			} else {
				c.output = fileRef{kind: refStdout}
			}
			continue
		}
		if parsing && len(arg) >= 2 && arg[0] == '-' && arg[1] == '-' {
			// Long options.
			if act := c.parseLong(arg, argv, &i); act != parseOK {
				return act
			}
			continue
		}
		if parsing && len(arg) >= 2 && arg[0] == '-' {
			if act := c.parseShort(arg, argv, &i); act != parseOK {
				return act
			}
			continue
		}
		// Positional.
		if act := c.addPositional(arg); act != parseOK {
			return act
		}
	}
	return parseOK
}

func (c *cliState) parseLong(arg string, argv []string, idx *int) int {
	switch arg {
	case "--help":
		return c.printHelp(false)
	case "--version":
		fmt.Fprint(os.Stdout, versionString)
		return parseExitOK
	case "--compress":
		c.mode = modeCompress
	case "--decompress", "--uncompress":
		c.mode = modeDecompress
	case "--test":
		c.mode = modeTest
		c.overwrite = true
	case "--force":
		c.overwrite = true
	case "--no-force":
		c.overwrite = false
	case "--keep":
		c.removeSrc = false
	case "--rm":
		c.removeSrc = true
	case "--quiet":
		c.displayLevel--
	case "--verbose":
		c.displayLevel++
	case "--multiple":
		c.setMultiple()
	case "--stdout", "--to-stdout":
		c.forceStdout = true
		c.output = fileRef{kind: refStdout}
	case "--list":
		c.mode = modeList
		c.setMultiple()
	case "--sparse":
		c.sparse = 2
	case "--no-sparse":
		c.sparse = 0
	case "--content-size":
		c.contentSize = true
		c.contentSizeMentioned = true
	case "--no-content-size":
		c.contentSize = false
	case "--no-frame-crc":
		c.contentChecksum = false
	case "--frame-crc":
		c.contentChecksum = true
	case "--favor-decSpeed":
		c.favorDecSpeed = true
	case "--best":
		c.cLevel = 12
	case "--fast":
		c.cLevel = -1
	default:
		if strings.HasPrefix(arg, "--fast=") {
			val := arg[len("--fast="):]
			if val == "" {
				return c.badUsage()
			}
			v, n, ok := readUnsigned(val)
			if !ok || n != len(val) {
				return c.badUsage()
			}
			c.cLevel = -int(v)
			return parseOK
		}
		if strings.HasPrefix(arg, "--threads") {
			rest := arg[len("--threads"):]
			if rest == "" {
				fmt.Fprintf(os.Stderr, "error: command cannot be separated from its argument by another command \n")
				return parseExitFail
			}
			if rest[0] != '=' {
				return c.badUsage()
			}
			val := rest[1:]
			v, remaining, ok := readSize(val)
			if !ok || remaining != "" {
				fmt.Fprintf(os.Stderr, "error: only numeric values with optional suffixes K, KB, KiB, M, MB, MiB are allowed \n")
				return parseExitFail
			}
			c.nbWorkers = int(v)
			return parseOK
		}
		return c.badUsage()
	}
	return parseOK
}

func (c *cliState) parseShort(arg string, argv []string, idx *int) int {
	rest := arg[1:]
	pos := 0
	for pos < len(rest) {
		ch := rest[pos]
		pos++
		switch {
		case ch >= '0' && ch <= '9':
			// Compression level: re-read from this digit.
			v, n, _ := readUnsigned(rest[pos-1:])
			c.cLevel = int(v)
			pos = pos - 1 + n
		case ch == 'V':
			fmt.Fprint(os.Stdout, versionString)
			return parseExitOK
		case ch == 'h':
			return c.printHelp(false)
		case ch == 'H':
			return c.printHelp(true)
		case ch == 'v':
			c.displayLevel++
		case ch == 'q':
			c.displayLevel--
		case ch == 'c':
			c.forceStdout = true
			c.output = fileRef{kind: refStdout}
		case ch == 'd':
			c.mode = modeDecompress
		case ch == 'z':
			c.mode = modeCompress
		case ch == 't':
			c.mode = modeTest
			c.overwrite = true
		case ch == 'f':
			c.overwrite = true
		case ch == 'k':
			c.removeSrc = false
		case ch == 'm':
			c.setMultiple()
		case ch == 'r':
			c.recursive = true
			c.setMultiple()
		case ch == 'l':
			c.legacy = true
		case ch == 'p':
			c.mainPause = true
		case ch == 'S':
			c.separate = true
		case ch == 'D':
			tail := rest[pos:]
			if tail != "" {
				c.dictName = tail
				c.dictSet = true
				pos = len(rest)
			} else {
				if *idx >= len(argv) {
					return c.badUsage()
				}
				c.dictName = argv[*idx]
				c.dictSet = true
				*idx++
			}
		case ch == 'B':
			tail := rest[pos:]
			if act := c.parseBlockSizeArg(tail); act != parseOK {
				return act
			}
			pos = len(rest)
		case ch == 'T':
			tail := rest[pos:]
			if tail == "" {
				c.nbWorkers = 0
				pos = len(rest)
				break
			}
			v, remaining, ok := readSize(tail)
			if !ok || remaining != "" {
				return c.badUsage()
			}
			c.nbWorkers = int(v)
			pos = len(rest)
		case ch == 'b':
			c.mode = modeBench
			c.setMultiple()
			tail := rest[pos:]
			if tail == "" {
				c.cLevel = 1
			} else if tail[0] >= '0' && tail[0] <= '9' {
				v, n, _ := readUnsigned(tail)
				c.cLevel = int(v)
				pos += n
			} else {
				c.cLevel = 1
			}
		case ch == 'e':
			tail := rest[pos:]
			if tail == "" {
				c.benchMaxLevel = 0
			} else if tail[0] >= '0' && tail[0] <= '9' {
				v, n, _ := readUnsigned(tail)
				c.benchMaxLevel = int(v)
				pos += n
			} else {
				c.benchMaxLevel = 0
			}
		case ch == 'i':
			tail := rest[pos:]
			if tail == "" {
				c.benchSeconds = 0
			} else {
				// Seconds may be given as a plain unsigned; a
				// fractional part is not accepted by the
				// original's integer reader for our purposes.
				v, n, ok := readUnsigned(tail)
				if !ok {
					return c.badUsage()
				}
				c.benchSeconds = float64(v)
				pos += n
			}
		default:
			return c.badUsage()
		}
	}
	return parseOK
}

func defaultNbWorkers() int {
	n := runtime.NumCPU()
	if n <= 1 {
		return 1
	}
	w := n - n/8 - 1
	if w < 1 {
		w = 1
	}
	return w
}

func (c *cliState) effectiveNbWorkers() int {
	if c.nbWorkers == 0 {
		return defaultNbWorkers()
	}
	if c.nbWorkers > 200 {
		return 200
	}
	return c.nbWorkers
}

func hasLZ4Suffix(name string) bool {
	return strings.HasSuffix(name, ".lz4")
}

func (c *cliState) startedCPU() {
	c.startTime = time.Now()
	c.startCPU = processCPUTime()
}

func main() {
	os.Exit(runMain())
}

func runMain() int {
	prog := "lz4"
	if len(os.Args) > 0 && os.Args[0] != "" {
		prog = filepath.Base(os.Args[0])
		// filepath.Base uses OS separator; emulate last '/' split.
		if idx := strings.LastIndex(os.Args[0], "/"); idx >= 0 {
			prog = os.Args[0][idx+1:]
			if prog == "" {
				prog = os.Args[0]
			}
		}
	}
	c := &cliState{
		prog:            prog,
		displayLevel:    2,
		mode:            modeAuto,
		cLevel:          1,
		benchSeconds:    3,
		contentChecksum: true,
		sparse:          1,
		stdinReader:     bufio.NewReaderSize(os.Stdin, 1<<16),
	}
	c.startedCPU()
	// Mode by program name.
	if strings.Contains(prog, "lz4cat") {
		c.mode = modeDecompress
		c.multiple = true
		c.forceStdout = true
		c.output = fileRef{kind: refStdout}
		c.overwrite = true
		c.displayLevel = 1
	} else if strings.Contains(prog, "unlz4") {
		c.mode = modeDecompress
	}
	act := c.parseArgs(os.Args[1:])
	if act == parseExitFail {
		return 1
	}
	if act == parseExitOK {
		return c.finish(0, false)
	}
	return c.dispatch()
}

// finish prints the verbose "Done" line (compression only, handled by the
// caller via doneCompression) and the optional pause, then returns code.
func (c *cliState) finish(code int, isCompression bool, inputBytes uint64) int {
	if isCompression && c.displayLevel >= 3 {
		elapsed := time.Since(c.startTime)
		cpu := processCPUTime() - c.startCPU
		secs := elapsed.Seconds()
		speed := 0.0
		if secs > 0 {
			speed = float64(inputBytes) / secs / (1024 * 1024)
		}
		load := 0
		if secs > 0 {
			load = int(cpu.Seconds() / secs * 100)
		}
		// Print elapsed with two decimals like %.2f, but keep at
		// least the measured speed even when it rounds to 0.00.
		fmt.Fprintf(os.Stderr, "Done in %.2f s ==> %.2f MiB/s  (cpu load : %d%%)\n", secs, speed, load)
	}
	if c.mainPause {
		fmt.Fprintf(os.Stderr, "Press enter to continue...\n")
		_, _ = c.stdinReader.ReadByte()
	}
	return code
}

