}

func (r fileRef) isUnset() bool { return r.kind == refUnset }
func (r fileRef) isStdin() bool { return r.kind == refStdin || (r.kind == refPath && r.path == "stdin") }
func (r fileRef) isStdout() bool {
	return r.kind == refStdout || (r.kind == refPath && r.path == "stdout")
}
func (r fileRef) isNull() bool { return r.kind == refNull || (r.kind == refPath && r.path == "null") }
func (r fileRef) displayName() string {
	switch r.kind {
	case refStdin:
		return "stdin"
	case refStdout:
		return "stdout"
	case refNull:
		return "null"
	default:
		return r.path
	}
}

type cliState struct {
	prog         string
	displayLevel int
	mode         opMode
	multiple     bool
	recursive    bool
	separate     bool // -S (bench: separate files)
	input        fileRef
	output       fileRef
	filenames    []string

	cLevel          int
	benchMaxLevel   int
	benchSeconds    float64
	nbWorkers       int
	blockSize       int // bytes, 0 = unset
