	contentChecksum bool
	contentSize     bool
	contentSizeMentioned bool
	favorDecSpeed   bool
	legacy          bool
	dictName        string
	dictSet         bool
	overwrite       bool
	removeSrc       bool
	mainPause       bool
	forceStdout     bool
	sparse          int // 0 off, 1 auto, 2 forced

