package main

import (
	"os"
	"strings"
	"syscall"
	"time"
)

func processCPUTime() time.Duration {
	var ru syscall.Rusage
	if err := syscall.Getrusage(syscall.RUSAGE_SELF, &ru); err != nil {
		return 0
	}
	return time.Duration(ru.Utime.Nano() + ru.Stime.Nano())
}

func isConsole(f *os.File) bool {
	if f == nil {
		return false
	}
	var st syscall.Stat_t
	if err := syscall.Fstat(int(f.Fd()), &st); err != nil {
		return false
	}
	return (st.Mode & syscall.S_IFMT) == syscall.S_IFCHR
}

func cStrerror(err error) string {
	if err == nil {
		return "Success"
	}
	if pe, ok := err.(*os.PathError); ok {
		err = pe.Err
	}
	if le, ok := err.(*os.LinkError); ok {
		err = le.Err
	}
	if en, ok := err.(syscall.Errno); ok {
		switch en {
		case syscall.ENOENT:
			return "No such file or directory"
		case syscall.EACCES:
			return "Permission denied"
		case syscall.EISDIR:
			return "Is a directory"
		case syscall.ENOTDIR:
			return "Not a directory"
		case syscall.EEXIST:
			return "File exists"
		case syscall.ENOSPC:
			return "No space left on device"
		case syscall.EPIPE:
			return "Broken pipe"
		case syscall.EINVAL:
			return "Invalid argument"
		case syscall.EPERM:
			return "Operation not permitted"
		case syscall.ENAMETOOLONG:
			return "File name too long"
		case syscall.ELOOP:
			return "Too many levels of symbolic links"
		default:
			s := en.Error()
			if s != "" {
				return strings.ToUpper(s[:1]) + s[1:]
			}
			return s
		}
	}
	return err.Error()
}

func isDirectoryPath(path string) bool {
	info, err := os.Stat(path)
	return err == nil && info.IsDir()
}
func isRegularPath(path string) bool {
	info, err := os.Stat(path)
	return err == nil && info.Mode().IsRegular()
}

func expandFilenames(names []string, recursive bool) []string {
	if !recursive {
		return names
	}
	var out []string
	for _, name := range names {
		if isDirectoryPath(name) {
			appendDirFiles(name, &out)
		} else {
			out = append(out, name)
		}
	}
	if len(out) == 0 {
		return names
	}
	return out
}

func appendDirFiles(dir string, out *[]string) {
	f, err := os.Open(dir)
	if err != nil {
		return
	}
	names, _ := f.Readdirnames(-1)
	f.Close()
	for _, e := range names {
		if e == "." || e == ".." {
			continue
		}
		path := dir + "/" + e
		if isDirectoryPath(path) {
			appendDirFiles(path, out)
		} else {
			*out = append(*out, path)
		}
	}
}

func setFileStatFrom(dst string, src string) {
	info, err := os.Stat(src)
	if err != nil || !info.Mode().IsRegular() {
		return
	}
	_ = os.Chmod(dst, info.Mode())
	atime := time.Now()
	if st, ok := info.Sys().(*syscall.Stat_t); ok {
		atime = time.Unix(st.Atim.Sec, st.Atim.Nsec)
	}
	mtime := time.Unix(info.ModTime().Unix(), 0)
	_ = os.Chtimes(dst, atime, mtime)
}

func baseName(path string) string {
	if idx := strings.LastIndex(path, "/"); idx >= 0 {
		return path[idx+1:]
	}
	return path
}

// truncatePad formats a filename like C's "%-30.30s" on bytes.
func truncatePad30(s string) string {
	b := []byte(s)
	if len(b) > 30 {
		b = b[:30]
	}
	out := string(b)
	if len(b) < 30 {
		out += strings.Repeat(" ", 30-len(b))
	}
	return out
}
