cat > src/ops.go << 'EOF'
package main

import (
	"bufio"
	"fmt"
	"io"
	"math"
	"os"
	"strings"
)

// ---------- dispatch ----------

func (c *cliState) dispatch() int {
	// Bench prints its own banner lines.
	if c.mode != modeBench {
		if c.displayLevel >= 3 {
			fmt.Fprint(os.Stderr, versionString)
			if c.displayLevel >= 4 {
				fmt.Fprint(os.Stderr, "_POSIX_C_SOURCE defined: 200809L\n_POSIX_VERSION defined: 200809L\nPLATFORM_POSIX_VERSION defined: 200809L\n")
			}
		}
	}
	// --content-size warning (printed once if the flag was ever given
	// and the resolved input is stdin).
	if c.contentSizeMentioned && c.displayLevel >= 2 && c.input.isStdin() && c.mode != modeBench {
		fmt.Fprintf(os.Stderr, "warning : --content-size cannot determine size when used with stdin\n")
	}
	switch c.mode {
	case modeBench:
		code, fatal := c.runBench()
		if fatal != nil {
			return c.handleFatal(fatal)
		}
		return c.finish(code, false, 0)
	case modeList:
		code, fatal := c.runList()
		if fatal != nil {
			return c.handleFatal(fatal)
		}
		return c.finish(code, false, 0)
	}
	// Determine compression vs decompression.
	isDecompress := false
	isTest := c.mode == modeTest
	switch c.mode {
	case modeCompress:
		isDecompress = false
	case modeDecompress, modeTest:
		isDecompress = true
	default: // auto
		if c.multiple && len(c.filenames) > 0 {
			isDecompress = hasLZ4Suffix(c.filenames[0])
		} else if !c.input.isUnset() && c.input.kind == refPath {
			isDecompress = hasLZ4Suffix(c.input.path)
		}
	}
	if c.multiple && len(c.filenames) > 0 {
		names := expandFilenames(c.filenames, c.recursive)
		var code int
		var fatal error
		var inBytes uint64
		if isDecompress {
			code, fatal = c.decompressMultiple(names, isTest)
		} else {
			code, inBytes, fatal = c.compressMultiple(names)
		}
		if fatal != nil {
			return c.handleFatal(fatal)
		}
		return c.finish(code, !isDecompress, inBytes)
	}
	// Single-file (or empty multiple) operation.
	inRef := c.input
	if inRef.isUnset() {
		inRef = fileRef{kind: refStdin}
	}
	outRef := c.output
	if isTest {
		outRef = fileRef{kind: refNull}
	} else if outRef.isUnset() {
		if inRef.isStdin() {
			outRef = fileRef{kind: refStdout}
		} else if !isDecompress {
			outName := inRef.path + ".lz4"
			outRef = fileRef{kind: refPath, path: outName}
			c.display(2, "Compressed filename will be : %s \n", outName)
		} else {
			if hasLZ4Suffix(inRef.path) && len(inRef.path) > 4 {
				outName := inRef.path[:len(inRef.path)-4]
				outRef = fileRef{kind: refPath, path: outName}
				c.display(2, "Decoding file %s \n", outName)
			} else {
				fmt.Fprintf(os.Stderr, "Cannot determine an output filename \n")
				c.badUsage()
				return 1
			}
		}
	}
	// Console checks.
	if inRef.isStdin() && isConsole(os.Stdin) {
		if c.displayLevel >= 1 {
			fmt.Fprintf(os.Stderr, "refusing to read from a console\n")
		}
		return c.finish(1, false, 0)
	}
	if outRef.isStdout() && isConsole(os.Stdout) && !c.forceStdout {
		if c.displayLevel >= 1 {
			fmt.Fprintf(os.Stderr, "refusing to write to console without -c \n")
		}
		return c.finish(1, false, 0)
	}
	var code int
	var fatal error
	var inBytes uint64
	if isDecompress {
		code, fatal = c.decompressSingle(inRef, outRef, c.displayLevel, isTest)
	} else {
		code, inBytes, fatal = c.compressSingle(inRef, outRef, c.displayLevel, true)
	}
	if fatal != nil {
		return c.handleFatal(fatal)
	}
	return c.finish(code, !isDecompress, inBytes)
}

func (c *cliState) handleFatal(fatal error) int {
	if fe, ok := fatal.(*fatalError); ok {
		if c.displayLevel >= 1 {
			fmt.Fprint(os.Stderr, fe.text)
		}
		return fe.code
	}
	// Generic I/O errors: report like a failed operation.
	if c.displayLevel >= 1 {
		fmt.Fprintf(os.Stderr, "%s\n", fatal.Error())
	}
	return 1
}

// opDisplay returns the effective display level for an operation whose
// destination is outRef, applying the stdout suppression rule.
func (c *cliState) opDisplay(outRef fileRef, level int) int {
	if outRef.isStdout() && level == 2 {
		return 1
	}
	return level
}

func (c *cliState) printThreadLine() {
	if c.displayLevel < 3 {
		return
	}
	if c.nbWorkers > 200 {
		fmt.Fprintf(os.Stderr, "Requested %d threads too large => automatically reduced to 200 \n", c.nbWorkers)
	} else if c.effectiveNbWorkers() != 1 {
		fmt.Fprintf(os.Stderr, "Using %d threads for compression \n", c.effectiveNbWorkers())
	}
}

// ---------- dictionary ----------

func (c *cliState) loadDictionary() ([]byte, error) {
	if !c.dictSet {
		return nil, nil
	}
	name := c.dictName
	if name == "stdin" {
		return nil, &fatalError{code: 40, text: "Error 40 : Error reading first chunk (4194304 bytes) of 'stdin'  \n"}
	}
	info, err := os.Stat(name)
	if err == nil && info.IsDir() {
		if c.displayLevel >= 1 {
			fmt.Fprintf(os.Stderr, "lz4: %s is a directory -- ignored \n", name)
		}
		return nil, throw(27, "Dictionary error : could not open dictionary file")
	}
	data, err := os.ReadFile(name)
	if err != nil {
		if c.displayLevel >= 1 {
			fmt.Fprintf(os.Stderr, "%s: %s \n", name, cStrerror(err))
		}
		return nil, throw(27, "Dictionary error : could not open dictionary file")
	}
	return data, nil
}

// ---------- src/dst handles ----------

type srcHandle struct {
	r         io.Reader
	file      *os.File
	isStdin   bool
	isRegular bool
	size      int64
	name      string
	ref       fileRef
}

type dstHandle struct {
	w         io.Writer
	file      *os.File
	isStdout  bool
	isNull    bool
	isRegular bool
	plainFile *os.File // underlying file even when wrapped (sparse)
	ref       fileRef
	sparseW   *sparseWriter
}

func (c *cliState) openSrc(ref fileRef, opDisp int) (*srcHandle, int) {
	h := &srcHandle{ref: ref, name: ref.displayName()}
	if ref.isStdin() {
		h.isStdin = true
		h.r = c.stdinReader
		if opDisp >= 4 {
			fmt.Fprintf(os.Stderr, "Using stdin for input \n")
		}
		return h, 0
	}
	path := ref.path
	if isDirectoryPath(path) {
		if opDisp >= 1 {
			fmt.Fprintf(os.Stderr, "lz4: %s is a directory -- ignored \n", path)
		}
		return nil, 1
	}
	f, err := os.Open(path)
	if err != nil {
		if opDisp >= 1 {
			fmt.Fprintf(os.Stderr, "%s: %s \n", path, cStrerror(err))
		}
		return nil, 1
	}
	h.file = f
	if st, serr := f.Stat(); serr == nil {
		h.isRegular = st.Mode().IsRegular()
		h.size = st.Size()
		// Use a buffered reader for decompression peek efficiency;
		// compression reads through it as well.
		h.r = bufio.NewReaderSize(f, 1<<16)
	} else {
		h.r = f
	}
	return h, 0
}

func (c *cliState) openDst(ref fileRef, opDisp int, forDecompress bool) (*dstHandle, int) {
	h := &dstHandle{ref: ref}
	if ref.isStdout() {
		h.isStdout = true
		h.plainFile = os.Stdout
		h.w = os.Stdout
		if opDisp >= 4 {
			fmt.Fprintf(os.Stderr, "Using stdout for output \n")
			if c.sparse == 1 {
				fmt.Fprintf(os.Stderr, "Sparse File Support automatically disabled on stdout ; to force-enable it, add --sparse command \n")
			}
		}
		return h, 0
	}
	if ref.isNull() {
		h.isNull = true
		f, err := os.OpenFile(os.DevNull, os.O_WRONLY, 0)
		if err != nil {
			h.w = io.Discard
			return h, 0
		}
		h.file = f
		h.plainFile = f
		h.w = f
		return h, 0
	}
	path := ref.path
	if _, err := os.Stat(path); err == nil && !c.overwrite {
		if !c.confirmOverwrite(path, opDisp) {
			return nil, 1
		}
	}
	f, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0666)
	if err != nil {
		if opDisp >= 1 {
			fmt.Fprintf(os.Stderr, "%s: %s\n", path, cStrerror(err))
		}
		return nil, 1
	}
	h.file = f
	h.plainFile = f
	h.w = f
	if st, serr := f.Stat(); serr == nil {
		h.isRegular = st.Mode().IsRegular()
	}
	return h, 0
}

func (c *cliState) confirmOverwrite(dst string, opDisp int) bool {
	if opDisp < 2 {
		fmt.Fprintf(os.Stderr, "%s already exists; not overwritten  \n", dst)
		return false
	}
	fmt.Fprintf(os.Stderr, "%s already exists; do you want to overwrite (y/N) ? ", dst)
	first, err := c.stdinReader.ReadByte()
	yes := false
	if err == nil {
		yes = first == 'y' || first == 'Y'
		if first != '\n' {
			for {
				b, err := c.stdinReader.ReadByte()
				if err != nil || b == '\n' {
					break
				}
			}
		}
	}
	if yes {
		return true
	}
	fmt.Fprintf(os.Stderr, "    not overwritten  \n")
	return false
}

// ---------- compression ----------

func (c *cliState) compPrefs(dict []byte, src *srcHandle) compSettings {
	s := compSettings{
		level:           c.cLevel,
		favorDecSpeed:   c.favorDecSpeed,
		blockChecksum:   c.blockChecksum,
		contentChecksum: c.contentChecksum,
		blockLinked:     c.blockLinked,
		dict:            dict,
		legacy:          c.legacy,
	}
	if c.blockSize == 0 {
		s.blockSizeID = 7
	} else {
		s.blockSizeID = blockIDForSize(c.blockSize, 7)
		if s.blockSizeID < 4 {
			s.blockSizeID = 4
		}
	}
	if c.contentSize && !c.legacy {
		if src != nil && src.isRegular {
			s.hasContentSize = true
			s.contentSize = uint64(src.size)
		} else if c.displayLevel >= 3 {
			fmt.Fprintf(os.Stderr, "Warning : cannot determine input content size \n")
		}
	}
	return s
}

func (c *cliState) compressSingle(inRef, outRef fileRef, level int, topLevel bool) (int, uint64, error) {
	if topLevel {
		c.printThreadLine()
	}
	dict, fatal := c.loadDictionary()
	if fatal != nil {
		return 0, 0, fatal
	}
	return c.compressSingleWithDict(inRef, outRef, level, dict)
}

func (c *cliState) compressSingleWithDict(inRef, outRef fileRef, level int, dict []byte) (int, uint64, error) {
	opDispBase := level
	src, code := c.openSrc(inRef, opDispBase)
	if src == nil {
		return code, 0, nil
	}
	defer func() {
		if src.file != nil {
			src.file.Close()
		}
	}()
	opDisp := c.opDisplay(outRef, opDispBase)
	dst, code := c.openDst(outRef, opDispBase, false)
	if dst == nil {
		return code, 0, nil
	}
	prefs := c.compPrefs(dict, src)
	inN, outN, err := compressFrameTo(dst.w, src.r, prefs)
	if dst.file != nil {
		dst.file.Close()
		dst.file = nil
	}
	if err != nil {
		// Write/read errors surface as exit code 1 with a message.
		if opDisp >= 1 {
			fmt.Fprintf(os.Stderr, "%s\n", err.Error())
		}
		return 1, uint64(inN), nil
	}
	// Statistics / progress (printed after compression, before any
	// removal error is raised by the caller-side remove step below).
	showStats := opDisp >= 2
	progress := ""
	if prefs.legacy {
		if inN > 0 {
			progress = "\rRead : 0 MiB   ==> inf%   "
		}
	} else if inN >= 4194304 {
		progress = "\rRead : 0 MiB   ==> inf%   "
	} else {
		denom := inN
		if denom == 0 {
			denom = 1
		}
		ratio := float64(outN) * 100.0 / float64(denom)
		progress = fmt.Sprintf("\rRead : %d MiB   ==> %.2f%%   ", inN>>20, ratio)
	}
	// Stat transfer and removal happen before the final summary in the
	// reference flow: a removal failure replaces the summary.
	if dst.plainFile != nil && !dst.isStdout && !dst.isNull && src.isRegular && dst.isRegular {
		setFileStatFrom(outRef.path, inRef.path)
	}
	if c.removeSrc {
		rmName := inRef.displayName()
		if inRef.kind == refPath {
			rmName = inRef.path
		}
		if rmErr := os.Remove(rmName); rmErr != nil {
			if showStats {
				fmt.Fprint(os.Stderr, progress)
			}
			return 0, uint64(inN), throw(50, "Remove error : %s: %s", rmName, cStrerror(rmErr))
		}
	}
	if showStats {
		denom := inN
		if denom == 0 {
			denom = 1
		}
		ratio := float64(outN) * 100.0 / float64(denom)
		tail := "\n"
		if prefs.legacy {
			tail = " \n"
		}
		fmt.Fprint(os.Stderr, progress)
		fmt.Fprint(os.Stderr, "\r"+strings.Repeat(" ", 79)+"\r")
		fmt.Fprintf(os.Stderr, "Compressed %d bytes into %d bytes ==> %.2f%%%s", inN, outN, ratio, tail)
	}
	return 0, uint64(inN), nil
}

func (c *cliState) compressMultiple(names []string) (int, uint64, error) {
	c.printThreadLine()
	dict, fatal := c.loadDictionary()
	if fatal != nil {
		return 0, 0, fatal
	}
	level := c.displayLevel - 1
	multiOutStdout := c.forceStdout || c.output.isStdout()
	firstIsStdin := len(names) > 0 && names[0] == "stdin"
	if firstIsStdin {
		multiOutStdout = true
	}
	errCount := 0
	var totalIn uint64
	for _, name := range names {
		inRef := fileRef{kind: refPath, path: name}
		var outRef fileRef
		if multiOutStdout {
			outRef = fileRef{kind: refStdout}
		} else {
			outRef = fileRef{kind: refPath, path: name + ".lz4"}
			if c.legacy {
				outRef = fileRef{kind: refPath, path: name + ".lz4"}
			}
		}
		code, inN, fatal := c.compressSingleWithDict(inRef, outRef, level, dict)
		totalIn += inN
		if fatal != nil {
			return 0, totalIn, fatal
		}
		errCount += code
	}
	return errCount, totalIn, nil
}

// ---------- decompression ----------

func (c *cliState) decompressSingle(inRef, outRef fileRef, level int, isTest bool) (int, error) {
	dict, fatal := c.loadDictionary()
	if fatal != nil {
		return 0, fatal
	}
	return c.decompressSingleWithDict(inRef, outRef, level, dict, isTest)
}

func (c *cliState) decompressSingleWithDict(inRef, outRef fileRef, level int, dict []byte, isTest bool) (int, error) {
	opDisp := c.opDisplay(outRef, level)
	dst, code := c.openDst(outRef, level, true)
	if dst == nil {
		return code, nil
	}
	// Sparse setup.
	sparseEnabled := false
	if c.sparse >= 1 {
		if dst.isStdout {
			sparseEnabled = c.sparse == 2
		} else {
			sparseEnabled = true
		}
	}
	outW := dst.w
	if sparseEnabled && dst.plainFile != nil && !dst.isNull {
		dst.sparseW = newSparseWriter(dst.plainFile)
		outW = dst.sparseW
	}
	src, code := c.openSrc(inRef, level)
	if src == nil {
		if dst.file != nil {
			dst.file.Close()
		}
		return code, nil
	}
	var r *bufio.Reader
	if src.isStdin {
		r = c.stdinReader
	} else if br, ok := src.r.(*bufio.Reader); ok {
		r = br
	} else {
		r = bufio.NewReaderSize(src.r, 1<<16)
	}
	passThrough := c.forceStdout && c.overwrite && outRef.isStdout()
	sink := newDecodeSink(outW)
	// For passthrough byte counting in verbose statistics we would need
	// a counting writer; passthrough normally targets stdout where the
	// summary is suppressed, so sink.total staying 0 is acceptable
	// except in verbose mode. Wrap when needed.
	var cw *countingWriter
	if passThrough {
		cw = &countingWriter{w: outW}
		sink.w = cw
	}
	decErr := decompressStream(r, sink, dict, passThrough)
	if cw != nil {
		sink.total = cw.n
		if cw.n > 0 && !sink.firstBurstKnown {
			sink.firstBurst = cw.n
			if sink.firstBurst > progressSegmentSize {
				sink.firstBurst = progressSegmentSize
			}
			sink.firstBurstKnown = true
		}
	}
	closeAll := func() {
		if src.file != nil {
			src.file.Close()
			src.file = nil
		}
		if dst.file != nil {
			dst.file.Close()
			dst.file = nil
		}
	}
	if decErr != nil {
		closeAll()
		if decErr == errSilentReturn1 {
			return 1, nil
		}
		// Emit a progress segment before a fatal error if the sink
		// had flushed at least one standard burst and stats are on.
		if opDisp >= 2 && sink.firstBurstKnown {
			fmt.Fprintf(os.Stderr, "\rDecompressed : %d MiB  ", sink.firstBurst>>20)
		}
		return 0, decErr
	}
	// Sparse end (may raise a fatal sparse error).
	if dst.sparseW != nil {
