		fmt.Fprintf(os.Stderr, "%s : decoded %d bytes \n", truncatePad30(inRef.displayName()), total)
	}
	_ = math.Inf
	return 0, nil
}

func (c *cliState) decompressMultiple(names []string, isTest bool) (int, error) {
	dict, fatal := c.loadDictionary()
	if fatal != nil {
		return 0, fatal
	}
	level := c.displayLevel - 1
	// Output routing for the multiple decompressor: stdout if forced,
	// if the pre-multiple output was a stdout/null special, if the
	// first file is the literal "stdin", or in test mode (whose
	// effective null output is treated as stdout by this path).
	toStdout := c.forceStdout || c.output.isStdout() || c.output.isNull() || isTest
	if len(names) > 0 && names[0] == "stdin" {
		toStdout = true
	}
	errCount := 0
	for _, name := range names {
		inRef := fileRef{kind: refPath, path: name}
		var outRef fileRef
		if toStdout {
			outRef = fileRef{kind: refStdout}
		} else {
			if !(len(name) > 4 && hasLZ4Suffix(name)) {
				if level >= 1 || c.displayLevel >= 1 {
					// The extension message is shown at the
					// multiple operation's display level; in
					// practice it appears unless errors are
					// suppressed (global level 0).
					if c.displayLevel >= 1 {
						fmt.Fprintf(os.Stderr, "File extension doesn't match expected LZ4_EXTENSION (.lz4); will not process file: %s\n", name)
					}
				}
				errCount++
				continue
			}
			outRef = fileRef{kind: refPath, path: name[:len(name)-4]}
		}
		code, fatal := c.decompressSingleWithDict(inRef, outRef, level, dict, false)
		if fatal != nil {
			return 0, fatal
		}
		errCount += code
	}
	return errCount, nil
}
