		n, err := io.ReadFull(r, bh[:])
		used += uint64(n)
		if err != nil || n < 4 {
			break
		}
		size := binary.LittleEndian.Uint32(bh[:]) & 0x7fffffff
		if size == 0 {
			break
		}
		skipped := skipCount(r, int64(size))
		used += uint64(skipped)
		if skipped < int64(size) {
			// Truncated block data.
			fi.compressed = used
			return fi, used, nil
		}
		if flg&0x10 != 0 {
			var ck [4]byte
			m, _ := io.ReadFull(r, ck[:])
			used += uint64(m)
		}
	}
	if fi.contentChecksum {
		var ck [4]byte
		n, _ := io.ReadFull(r, ck[:])
		used += uint64(n)
	}
	fi.compressed = used
	return fi, used, nil
}
