func humanSize(v uint64) string {
	if v < 1024 {
		return fmt.Sprintf("%.2f", float64(v))
	}
	if v < 1024*1024 {
		return fmt.Sprintf("%.2fK", float64(v)/1024.0)
	}
	if v < 1024*1024*1024 {
		return fmt.Sprintf("%.2fM", float64(v)/(1024.0*1024.0))
	}
	return fmt.Sprintf("%.2fG", float64(v)/(1024.0*1024.0*1024.0))
