// listFile parses the frames of one file without decompressing blocks.
// It returns code 1 for an unrecognised leading format.
func listFile(path string) ([]frameInfo, uint64, int, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, 0, 1, nil
	}
	defer f.Close()
	st, _ := f.Stat()
	fileSize := uint64(st.Size())
	r := bufio.NewReaderSize(f, 1<<16)
	var infos []frameInfo
	var consumed uint64
	for {
		b, _ := r.Peek(4)
		if len(b) == 0 {
			break
		}
		if len(b) < 4 {
			if len(infos) == 0 {
				return nil, fileSize, 1, nil
			}
			return nil, fileSize, 0, throw(40, "Unrecognized header : Magic Number unreadable")
		}
		magic := binary.LittleEndian.Uint32(b)
		if isSkippableMagic(magic) {
			if _, err := r.Discard(4); err != nil {
				break
			}
			var szb [4]byte
			n, _ := io.ReadFull(r, szb[:])
			consumed += uint64(4 + n)
			if n < 4 {
				infos = append(infos, frameInfo{typ: "SkippableFrame", compressed: 4 + uint64(n)})
				break
			}
			size := uint64(binary.LittleEndian.Uint32(szb[:]))
			skipped := skipCount(r, int64(size))
			consumed += size
			_ = skipped
			infos = append(infos, frameInfo{typ: "SkippableFrame", compressed: 8 + size})
			continue
		}
		if magic == legacyMagic {
			startConsumed := consumed
			if _, err := r.Discard(4); err != nil {
				break
			}
			consumed += 4
			for {
				bb, _ := r.Peek(4)
				if len(bb) < 4 {
					consumed += uint64(len(bb))
					// Discard remainder.
					_, _ = r.Discard(len(bb))
					break
				}
				sz := binary.LittleEndian.Uint32(bb)
				if sz > legacyBlockMaxCompressed {
					break
				}
				_, _ = r.Discard(4)
				consumed += 4
				skipped := skipCount(r, int64(sz))
				consumed += uint64(skipped)
				if skipped < int64(sz) {
					break
				}
			}
			infos = append(infos, frameInfo{typ: "LegacyFrame", compressed: consumed - startConsumed})
			// If we broke on EOF, the outer Peek will end.
			if bb, _ := r.Peek(1); len(bb) == 0 {
				break
			}
			continue
		}
		if magic == frameMagic {
			fi, used, ferr := listLZ4Frame(r)
			if ferr != nil {
				return nil, fileSize, 0, ferr
			}
			consumed += used
