	// size when the walk ended at EOF (truncated frames).
	var sum uint64
	for _, fi := range infos {
		sum += fi.compressed
	}
	if sum != fileSize && len(infos) > 0 {
		// Attribute any discrepancy to the last frame.
		if fileSize > sum {
			infos[len(infos)-1].compressed += fileSize - sum
		} else if infos[len(infos)-1].compressed > (sum - fileSize) {
			infos[len(infos)-1].compressed -= (sum - fileSize)
		}
	}
	_ = consumed
	return infos, fileSize, 0, nil
}

func skipCount(r *bufio.Reader, n int64) int64 {
	var done int64
	for n > 0 {
		chunk := n
		if chunk > 1<<20 {
			chunk = 1 << 20
		}
		sk, err := r.Discard(int(chunk))
		done += int64(sk)
		n -= int64(sk)
		if err != nil || sk == 0 {
			break
		}
	}
	return done
}

func listLZ4Frame(r *bufio.Reader) (frameInfo, uint64, error) {
	var used uint64
	// Magic.
	if _, err := r.Discard(4); err != nil {
		return frameInfo{typ: "LZ4Frame", compressed: 4}, 4, nil
	}
	used += 4
	fi := frameInfo{typ: "LZ4Frame"}
	flg, err := r.ReadByte()
	if err != nil {
		fi.compressed = used
		return fi, used, nil
	}
	used++
	bd, err := r.ReadByte()
	if err != nil {
		fi.compressed = used
		return fi, used, nil
	}
	used++
	fi.blockID = int(bd>>4) & 7
	fi.blockLinked = flg&0x20 == 0
	fi.hasBlockInfo = true
	fi.contentChecksum = flg&0x04 != 0
	if flg&0x08 != 0 {
		var tmp [8]byte
		n, _ := io.ReadFull(r, tmp[:])
		used += uint64(n)
		if n == 8 {
			fi.uncompressed = binary.LittleEndian.Uint64(tmp[:])
			fi.hasUncompressed = true
		}
	}
	if flg&0x01 != 0 {
		var tmp [4]byte
		n, _ := io.ReadFull(r, tmp[:])
		used += uint64(n)
	}
	if _, err := r.ReadByte(); err == nil {
		used++
	}
	// Blocks.
	for {
		var bh [4]byte
		n, err := io.ReadFull(r, bh[:])
		used += uint64(n)
		if err != nil || n < 4 {
			break
		}
		size := binary.LittleEndian.Uint32(bh[:]) & 0x7fffffff
		if size == 0 {
			break
		}
		skipped := skipCount(r, int64(size))
		used += uint64(skipped)
		if skipped < int64(size) {
			// Truncated block data.
			fi.compressed = used
			return fi, used, nil
		}
		if flg&0x10 != 0 {
			var ck [4]byte
			m, _ := io.ReadFull(r, ck[:])
			used += uint64(m)
		}
	}
	if fi.contentChecksum {
		var ck [4]byte
		n, _ := io.ReadFull(r, ck[:])
		used += uint64(n)
	}
	fi.compressed = used
	return fi, used, nil
}
