func (c *cliState) runBench() (int, error) {
	// Verbose banner lines for the bench path.
	if c.displayLevel >= 3 {
		fmt.Fprintf(os.Stderr, "- test >= %s seconds per compression / decompression -\n", formatBenchSeconds(c.benchSeconds))
		fmt.Fprint(os.Stderr, versionString)
		if c.displayLevel >= 4 {
			fmt.Fprint(os.Stderr, "_POSIX_C_SOURCE defined: 200809L\n_POSIX_VERSION defined: 200809L\nPLATFORM_POSIX_VERSION defined: 200809L\n")
			bsKB := c.blockSize >> 10
			if c.blockSize == 0 {
				bsKB = 4096
			}
			fmt.Fprintf(os.Stderr, "Blocks size : %d KB\n", bsKB)
		}
	}
	dict, fatal := c.loadBenchDictionary()
	if fatal != nil {
		return 0, fatal
	}
	names := expandFilenames(c.filenames, c.recursive)
	var datasets []benchDataset
	if len(names) == 0 {
		datasets = []benchDataset{{name: "Lorem ipsum", data: generateLorem(10000000)}}
	} else if c.separate {
		for _, name := range names {
			if isDirectoryPath(name) {
				if c.displayLevel >= 2 {
					fmt.Fprintf(os.Stderr, "Ignoring %s directory...       \n", name)
				}
				return 0, throwNoSpace(12, "no data to bench")
			}
			data, err := os.ReadFile(name)
			if err != nil {
				return 0, throwNoSpace(10, "impossible to open file %s", name)
			}
			if len(data) == 0 {
				return 0, throwNoSpace(12, "no data to bench")
			}
			if c.displayLevel >= 4 {
				fmt.Fprintf(os.Stderr, "Loading %s...       \r", name)
			}
			datasets = append(datasets, benchDataset{name: name, data: data})
		}
	} else {
		var all []byte
		loaded := 0
		for _, name := range names {
			if isDirectoryPath(name) {
				if c.displayLevel >= 1 {
					fmt.Fprintf(os.Stderr, "Ignoring %s directory...       \n", name)
				}
				continue
			}
			data, err := os.ReadFile(name)
			if err != nil {
				return 0, throwNoSpace(10, "impossible to open file %s", name)
			}
			if c.displayLevel >= 4 {
				fmt.Fprintf(os.Stderr, "Loading %s...       \r", name)
			}
			all = append(all, data...)
			loaded++
		}
		if len(all) == 0 {
			return 0, throwNoSpace(12, "no data to bench")
		}
		name := names[0]
		if len(names) > 1 {
			name = fmt.Sprintf(" %d files", len(names))
		}
		_ = loaded
		datasets = []benchDataset{{name: name, data: all}}
	}
	startLevel := c.cLevel
	maxLevel := c.benchMaxLevel
	if maxLevel < startLevel {
		maxLevel = startLevel
	}
	if maxLevel > 12 {
		maxLevel = 12
	}
	if startLevel > 12 {
		// The benchmark loop clamps the displayed level too; emulate
		// by treating any start above 12 as 12 for iteration but the
		// quiet label below uses the clamped effective level through
		// benchOneLevel's own clamping.
	}
	if maxLevel > startLevel && c.displayLevel >= 2 {
		fmt.Fprintf(os.Stderr, "Benchmarking levels from %d to %d\n", displayBenchLevel(startLevel), displayBenchLevel(maxLevel))
	}
	for _, ds := range datasets {
		if c.displayLevel == 1 {
			fmt.Fprintf(os.Stderr, "bench 1.10.0 : input %d bytes, %s seconds, %d KB blocks\n", len(ds.data), formatBenchSeconds(c.benchSeconds), c.blockSize>>10)
		}
		for level := startLevel; level <= maxLevel; level++ {
			c.benchOneLevel(ds, level, dict)
			if level == maxLevel {
				break
			}
		}
	}
	return 0, nil
}

func displayBenchLevel(level int) int {
	if level > 12 {
		return 12
	}
	return level
}

func formatBenchSeconds(s float64) string {
	// The original prints the seconds value as an integer in these
	// headers (the -i argument is read as an unsigned).
	return fmt.Sprintf("%d", int(s))
}

func (c *cliState) benchOneLevel(ds benchDataset, level int, dict []byte) {
	data := ds.data
	// Split into blocks.
	blockSize := c.blockSize
	var blocks [][]byte
	if blockSize <= 0 || blockSize >= len(data) {
		blocks = [][]byte{data}
	} else {
		for i := 0; i < len(data); i += blockSize {
			end := i + blockSize
			if end > len(data) {
				end = len(data)
			}
			blocks = append(blocks, data[i:end])
		}
	}
	effLevel := level
	// Compress once to obtain sizes and the compressed blocks.
	compressed := make([][]byte, len(blocks))
	compTotal := 0
	for i, blk := range blocks {
		cb := c.benchCompressOne(blk, effLevel, dict)
		// The benchmark counts the raw block size, except when the
		// compressor cannot shrink the block the count is the
		// original size (as returned sizes above the input are
		// still real block outputs; the reference bench uses the
		// returned compressed size, falling back to the input size
		// when compression returns 0).
		compressed[i] = cb
		compTotal += len(cb)
	}
	spinnerName := ds.name
	// Timed compression loop.
	compSpeed := c.benchTimed(func() {
		for _, blk := range blocks {
			_ = c.benchCompressOne(blk, effLevel, dict)
		}
	}, len(data), spinnerName, compTotal, true)
	// Timed decompression loop.
	decompSpeed := c.benchTimed(func() {
		for i, blk := range blocks {
			var hist []byte
			if len(dict) > 0 {
				hist = tailBytes(dict, 65535)
			}
			out, err := decodeBlockBench(compressed[i], hist, len(blk))
			if err == nil && len(out) != len(blk) {
				// Some bench-compressed blocks may be stored
				// effectively raw (size >= input); treat the
				// stored size as the input for timing only.
				_ = out
			}
		}
	}, len(data), spinnerName, compTotal, false)
	ratio := 0.0
	if compTotal > 0 {
		ratio = float64(len(data)) / float64(compTotal)
	}
	if c.displayLevel == 1 {
		fmt.Fprintf(os.Stdout, "-%d %12d (%.3f) %.2f MB/s %.1f MB/s  %s \n", level, compTotal, ratio, compSpeed, decompSpeed, ds.name)
		return
	}
	if c.displayLevel >= 2 {
		// Final result line (stdout), matching the split of the
		// reference output: a compression result segment, a combined
		// segment, then the level marker.
