		if len(names) > 1 {
			name = fmt.Sprintf(" %d files", len(names))
		}
		_ = loaded
		datasets = []benchDataset{{name: name, data: all}}
	}
	startLevel := c.cLevel
	maxLevel := c.benchMaxLevel
	if maxLevel < startLevel {
		maxLevel = startLevel
	}
	if maxLevel > 12 {
		maxLevel = 12
	}
	if startLevel > 12 {
		// The benchmark loop clamps the displayed level too; emulate
		// by treating any start above 12 as 12 for iteration but the
		// quiet label below uses the clamped effective level through
		// benchOneLevel's own clamping.
	}
	if maxLevel > startLevel && c.displayLevel >= 2 {
		fmt.Fprintf(os.Stderr, "Benchmarking levels from %d to %d\n", displayBenchLevel(startLevel), displayBenchLevel(maxLevel))
	}
	for _, ds := range datasets {
		if c.displayLevel == 1 {
			fmt.Fprintf(os.Stderr, "bench 1.10.0 : input %d bytes, %s seconds, %d KB blocks\n", len(ds.data), formatBenchSeconds(c.benchSeconds), c.blockSize>>10)
		}
		for level := startLevel; level <= maxLevel; level++ {
			c.benchOneLevel(ds, level, dict)
			if level == maxLevel {
				break
			}
		}
	}
	return 0, nil
}

func displayBenchLevel(level int) int {
	if level > 12 {
		return 12
	}
	return level
}

func formatBenchSeconds(s float64) string {
	// The original prints the seconds value as an integer in these
	// headers (the -i argument is read as an unsigned).
	return fmt.Sprintf("%d", int(s))
}

func (c *cliState) benchOneLevel(ds benchDataset, level int, dict []byte) {
	data := ds.data
	// Split into blocks.
	blockSize := c.blockSize
	var blocks [][]byte
	if blockSize <= 0 || blockSize >= len(data) {
		blocks = [][]byte{data}
	} else {
		for i := 0; i < len(data); i += blockSize {
			end := i + blockSize
			if end > len(data) {
				end = len(data)
			}
			blocks = append(blocks, data[i:end])
		}
	}
	effLevel := level
	// Compress once to obtain sizes and the compressed blocks.
	compressed := make([][]byte, len(blocks))
	compTotal := 0
	for i, blk := range blocks {
		cb := c.benchCompressOne(blk, effLevel, dict)
		// The benchmark counts the raw block size, except when the
		// compressor cannot shrink the block the count is the
		// original size (as returned sizes above the input are
		// still real block outputs; the reference bench uses the
		// returned compressed size, falling back to the input size
		// when compression returns 0).
		compressed[i] = cb
		compTotal += len(cb)
	}
	spinnerName := ds.name
	// Timed compression loop.
	compSpeed := c.benchTimed(func() {
		for _, blk := range blocks {
			_ = c.benchCompressOne(blk, effLevel, dict)
		}
	}, len(data), spinnerName, compTotal, true)
	// Timed decompression loop.
	decompSpeed := c.benchTimed(func() {
		for i, blk := range blocks {
			var hist []byte
			if len(dict) > 0 {
				hist = tailBytes(dict, 65535)
			}
			out, err := decodeBlockBench(compressed[i], hist, len(blk))
			if err == nil && len(out) != len(blk) {
				// Some bench-compressed blocks may be stored
				// effectively raw (size >= input); treat the
				// stored size as the input for timing only.
				_ = out
			}
		}
	}, len(data), spinnerName, compTotal, false)
	ratio := 0.0
	if compTotal > 0 {
		ratio = float64(len(data)) / float64(compTotal)
	}
	if c.displayLevel == 1 {
		fmt.Fprintf(os.Stdout, "-%d %12d (%.3f) %.2f MB/s %.1f MB/s  %s \n", level, compTotal, ratio, compSpeed, decompSpeed, ds.name)
		return
	}
	if c.displayLevel >= 2 {
		// Final result line (stdout), matching the split of the
		// reference output: a compression result segment, a combined
		// segment, then the level marker.
		name17 := trunc17(spinnerName)
		fmt.Fprintf(os.Stdout, " /-%-17s : %9d -> %10d (%.3f),%6.1f MB/s\r", name17, len(data), compTotal, ratio, compSpeed)
		fmt.Fprintf(os.Stdout, " =-%-17s : %9d -> %10d (%.3f),%6.1f MB/s,%7.1f MB/s\r", name17, len(data), compTotal, ratio, compSpeed, decompSpeed)
		fmt.Fprintf(os.Stdout, "%2d#\n", displayBenchLevel(level))
	}
}

// benchTimed runs fn repeatedly for at least c.benchSeconds (with a small
// minimum number of iterations so that -i0 still measures something) and
// returns throughput in MB/s (bytes are the input size). It also emits
// the initial spinner segment to stderr for the interactive display.
func (c *clicStateUnused) unused() {}

type clicStateUnused struct{}

func (c *cliState) benchTimed(fn func(), inputBytes int, name string, compTotal int, isCompress bool) float64 {
	if c.displayLevel >= 2 && isCompress {
		fmt.Fprintf(os.Stderr, "\r"+spaces79()+"\r")
		fmt.Fprintf(os.Stderr, " |-%-17s : %9d ->\r", trunc17(name), inputBytes)
	}
	minSeconds := c.benchSeconds
	iterations := 0
	start := time.Now()
	// At least a few iterations to reduce timer noise on tiny inputs.
	minIter := 3
	if inputBytes >= 1<<20 {
		minIter = 1
	}
	for {
		fn()
		iterations++
		elapsed := time.Since(start).Seconds()
		if iterations >= minIter && elapsed >= minSeconds {
			if elapsed <= 0 {
				elapsed = 1e-9
			}
			return float64(inputBytes) * float64(iterations) / elapsed / 1e6
		}
		if iterations > 1000000 {
			elapsed := time.Since(start).Seconds()
			if elapsed <= 0 {
				elapsed = 1e-9
			}
			return float64(inputBytes) * float64(iterations) / elapsed / 1e6
		}
	}
}

func spaces79() string {
	const s = "                                                                               "
	return s
}

func trunc17(name string) string {
	b := []byte(name)
	if len(b) > 17 {
		b = b[:17]
	}
	return string(b)
}

func (c *cliState) benchCompressOne(src []byte, level int, dict []byte) []byte {
	// Bench level mapping mirrors the frame mapping, except that the
	// level can be negative via --fast after -b.
	s := compSettings{level: level, favorDecSpeed: c.favorDecSpeed, dict: dict}
	if len(dict) > 0 {
		bc := newBlockCompressor(s, true)
		return bc.compressBlock(src)
	}
	if level >= 2 {
		lvl := level
		if lvl > 12 {
			lvl = 12
		}
		return compressBlockHCOneShot(src, lvl, c.favorDecSpeed)
	}
	return compressBlockFastOneShot(src, frameFastAcceleration(level))
}

// decodeBlockBench decodes a bench block; bench blocks are raw LZ4 blocks
// whose exact output size is known.
func decodeBlockBench(block, history []byte, maxOut int) ([]byte, error) {
	return decodeBlock(block, history, maxOut)
}
