import subprocess,os,struct
EXE=os.path.abspath('./executable');os.makedirs('/tmp/dicttest',exist_ok=True)
def seqs(data):
 r=subprocess.run([EXE,'-D','dict','-c','-'],input=data,capture_output=True,cwd='/tmp/dicttest');out=r.stdout;bs=struct.unpack_from('<I',out,7)[0];blk=out[11:11+(bs&0x7fffffff)]
 # parse first token
 t=blk[0];lit=t>>4;i=1
 if lit==15:
  while True:
   x=blk[i];i+=1;lit+=x
   if x!=255:break
 lits=blk[i:i+lit];i+=lit
 if i>=len(blk):return (lit,0,0,lits)
 off=struct.unpack_from('<H',blk,i)[0];ml=(t&15)+4
 return (lit,off,ml,lits)
marker=b"MARKER12"
for dictlen in [40,100]:
 for marker_start in range(dictlen-20,dictlen):
  if marker_start+8>dictlen: continue
  d=bytearray(b"abcdefghij"*(dictlen//10+1));d=d[:dictlen];d[marker_start:marker_start+8]=marker
  open('/tmp/dicttest/dict','wb').write(bytes(d))
  data=marker+b"ENDLIT12345"
  print("len",dictlen,"marker at",marker_start,"fromEndStart",dictlen-marker_start,seqs(data))
