import struct

def u32(b,i): return struct.unpack_from('<I',b,i)[0]
def u64(b,i): return struct.unpack_from('<Q',b,i)[0]
def hf5(seq,log=12): return (((seq<<24)&0xffffffffffffffff)*889523592379 &0xffffffffffffffff)>>(64-log)

class StreamSim:
 def __init__(self,window,accel=1,init_table=-1):
  self.w=window;self.table=[init_table]*(1<<12);self.accel=accel
 def put(self,p):
  if 0<=p<=len(self.w)-4:self.table[hf5(u64(self.w,p))]=p
 def get(self,p):return self.table[hf5(u64(self.w,p))]
 def compress_block(self,start,end,first=False,start_mode=0,insert_from=None):
  w=self.w;seqs=[]
  if end-start<=12:return [(end-start,0,0)]
  if first:
   self.put(0);ip=1
  else:
   if insert_from is not None:
    for p in range(insert_from,start):self.put(p)
   ip=start if start_mode==0 else start+1
   if start_mode==1:self.put(start)
  anchor=start;matchLimit=end-12;lastRun=end-5
  while True:
   forward=ip;step=1;searchNb=self.accel<<6;cand=-1
   while True:
    if forward>matchLimit:
     seqs.append((end-anchor,0,0));return seqs
    cur=forward;cand=self.get(cur);forward+=step;step=searchNb>>6;searchNb+=1;self.put(cur)
    if cand>=0 and cand<cur and cur-cand<=65535 and u32(w,cand)==u32(w,cur):
     ip=cur;break
   while ip>anchor and cand>0 and w[ip-1]==w[cand-1]:
    ip-=1;cand-=1
   while True:
    litlen=ip-anchor;mlen=4
    while ip+mlen<lastRun and w[ip+mlen]==w[cand+mlen]:mlen+=1
    seqs.append((litlen,ip-cand,mlen));anchor=ip+mlen;ip=anchor
    if ip>matchLimit:
     seqs.append((end-anchor,0,0));return seqs
    self.put(ip-2);cand2=self.get(ip);self.put(ip)
    if cand2>=0 and cand2<ip and ip-cand2<=65535 and u32(w,cand2)==u32(w,ip):
     cand=cand2;continue
    ip+=1;break
