s=open(p).read()
# fastTable: add init-aware constructor
s=s.replace('''func newFastTable(hash5 bool, log uint) *fastTable {
\treturn &fastTable{entries: make([]int32, 1<<log), log: log, hash5: hash5}
}''','''func newFastTable(hash5 bool, log uint) *fastTable {
\treturn newFastTableInit(hash5, log, 0)
}

func newFastTableInit(hash5 bool, log uint, init int32) *fastTable {
\tt := &fastTable{entries: make([]int32, 1<<log), log: log, hash5: hash5}
\tif init != 0 {
\t\tfor i := range t.entries {
\t\t\tt.entries[i] = init
\t\t}
\t}
\treturn t
}''')
# Replace fastStream struct + constructor + loadDict + compressBlock with revised version
import re
start=s.index('// fastStream is a stateful')
end=s.index('// decodeBlock decodes')
new_block=r'''// fastStream is a stateful fast compressor used for block-linked frames
// and dictionary compression. It always uses the 5-byte hash table.
type fastStream struct {
	table *fastTable
	// history holds the retained bytes before the current block
	// (dictionary or tail of previous input), limited logically by the
	// 64KB window during candidate checks.
	history   []byte
	firstUsed bool
	hasDict   bool
	accel     int
}

func newFastStream(acceleration int, dict []byte) *fastStream {
	fs := &fastStream{accel: acceleration}
	if len(dict) > 0 {
		// A dictionary-backed stream uses a table whose unset
		// entries are invalid (-1) rather than position 0.
		fs.table = newFastTableInit(true, 12, -1)
		d := dict
		if len(d) > 65535 {
			d = d[len(d)-65535:]
		}
		fs.history = append(fs.history[:0], d...)
		fs.hasDict = true
	} else {
		fs.table = newFastTableInit(true, 12, 0)
	}
	return fs
}

// compressBlock compresses one block in stream mode, updating history.
func (fs *fastStream) compressBlock(src []byte) []byte {
