// recognised, 2 corrupted legacy frame. unknownPos is set (to the offset
// just after an unknown magic) when an unknown magic is encountered.
func listFile(path string) ([]frameInfo, uint64, int, int64, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, 0, 1, -1, nil
	}
	defer f.Close()
	st, _ := f.Stat()
	fileSize := uint64(st.Size())
	r := bufio.NewReaderSize(f, 1<<16)
	var infos []frameInfo
	var logicalPos uint64
	for {
		b, _ := r.Peek(4)
		if len(b) == 0 {
			break
		}
		if len(b) < 4 {
			return infos, fileSize, 0, -1, throw(40, "Unrecognized header : Magic Number unreadable")
		}
		magic := binary.LittleEndian.Uint32(b)
		if isSkippableMagic(magic) {
