			}
			size := uint64(binary.LittleEndian.Uint32(szb[:]))
			skipCount(r, int64(size))
			infos = append(infos, frameInfo{typ: "SkippableFrame", compressed: 8 + size})
			logicalPos += 8 + size
			continue
		}
