			if _, err := r.Discard(4); err != nil {
				break
			}
			var frameSize uint64 = 4
			corrupt := false
			for {
				bb, _ := r.Peek(4)
				if len(bb) == 0 {
					break
				}
				if len(bb) < 4 {
					corrupt = true
					break
				}
				sz := binary.LittleEndian.Uint32(bb)
				if sz > legacyBlockMaxCompressed {
					break
				}
				_, _ = r.Discard(4)
				frameSize += 4
				skipCount(r, int64(sz))
				frameSize += uint64(sz)
			}
			if corrupt {
				return infos, fileSize, 2, -1, nil
			}
			infos = append(infos, frameInfo{typ: "LegacyFrame", compressed: frameSize})
			logicalPos += frameSize
			if bb, _ := r.Peek(1); len(bb) == 0 {
				break
			}
			continue
		}
