			fi, used, ferr := listLZ4Frame(r)
			if ferr == errListBadFormat {
				return infos, fileSize, 1, -1, nil
			}
			if ferr != nil {
				return infos, fileSize, 0, -1, ferr
			}
			infos = append(infos, fi)
			logicalPos += used
			if bb, _ := r.Peek(1); len(bb) == 0 {
				break
			}
			continue
		}
		// Unknown magic.
		return infos, fileSize, 1, int64(logicalPos + 4), nil
	}
	if len(infos) == 0 {
		return infos, fileSize, 1, -1, nil
	}
	return infos, fileSize, 0, -1, nil
}

var errListBadFormat = fmt.Errorf("bad frame format")

func listLZ4Frame(r *bufio.Reader) (frameInfo, uint64, error) {
	var used uint64
	if _, err := r.Discard(4); err != nil {
		return frameInfo{typ: "LZ4Frame", compressed: 4}, 4, errListBadFormat
	}
	used += 4
	fi := frameInfo{typ: "LZ4Frame"}
	flg, err1 := r.ReadByte()
	bd, err2 := r.ReadByte()
	if err1 != nil || err2 != nil {
		return fi, used, errListBadFormat
	}
	used += 2
	hdrPlain := []byte{flg, bd}
	if flg&0x08 != 0 {
		var tmp [8]byte
		n, err := io.ReadFull(r, tmp[:])
		used += uint64(n)
		if err != nil {
			return fi, used, errListBadFormat
		}
		hdrPlain = append(hdrPlain, tmp[:]...)
		if v := binary.LittleEndian.Uint64(tmp[:]); v != 0 {
			fi.uncompressed = v
			fi.hasUncompressed = true
		}
	}
	if flg&0x01 != 0 {
		var tmp [4]byte
		n, err := io.ReadFull(r, tmp[:])
		used += uint64(n)
		if err != nil {
			return fi, used, errListBadFormat
		}
		hdrPlain = append(hdrPlain, tmp[:]...)
	}
	hc, err := r.ReadByte()
	if err != nil {
		return fi, used, errListBadFormat
	}
	used++
	if (bd>>4) > 7 || (flg&0x02 != 0) || (flg>>6) != 1 || blockMaxForID(int(bd>>4)) == 0 || (bd&0x0f != 0) || byte((xxhash32(hdrPlain, 0)>>8)&0xff) != hc {
		return fi, used, errListBadFormat
	}
	fi.blockID = int(bd >> 4)
	fi.blockLinked = flg&0x20 == 0
	fi.hasBlockInfo = true
	fi.contentChecksum = flg&0x04 != 0
	endMarkSeen := false
	for {
		bb, _ := r.Peek(4)
		if len(bb) == 0 {
			break
		}
		var hdrBytes [4]byte
		copy(hdrBytes[:], bb)
		_, _ = r.Discard(len(bb))
		used += 4
		size := binary.LittleEndian.Uint32(hdrBytes[:]) & 0x7fffffff
		if size == 0 {
			endMarkSeen = true
			break
		}
		used += uint64(size)
		skipCount(r, int64(size))
		if flg&0x10 != 0 {
			used += 4
			skipCount(r, 4)
		}
	}
	if fi.contentChecksum && endMarkSeen {
		used += 4
		skipCount(r, 4)
	}
	fi.compressed = used
	return fi, used, nil
}
