import os,pty,subprocess,time,shutil
ORIG=os.path.abspath("./executable");OURS="/tmp/oursdir/executable"
def run(exe,args,setup):
 root="/tmp/ttyroot_"+("orig" if exe==ORIG else "ours")
 shutil.rmtree(root,ignore_errors=True);os.makedirs(root)
 for n,d in setup.items():open(os.path.join(root,n),'wb').write(d)
 master,slave=pty.openpty()
 p=subprocess.Popen([exe]+args,stdin=slave,stdout=slave,stderr=slave,cwd=root,close_fds=True)
 os.close(slave);out=b"";os.set_blocking(master,False);start=time.time()
 while time.time()-start<3:
  if p.poll() is not None:
   try:
    while True:
     c=os.read(master,65536)
     if not c:break
     out+=c
   except Exception:pass
   break
  try:out+=os.read(master,65536)
  except BlockingIOError:time.sleep(.02)
  except OSError:break
 timed=p.poll() is None
 if timed:p.kill();p.wait()
 os.close(master)
 files={}
 for dp,ds,fs in os.walk(root):
  for f in fs:files[os.path.relpath(os.path.join(dp,f),root)]=open(os.path.join(dp,f),'rb').read()
 return (p.returncode,out,files,timed)
