cases=[
 ([],{}),(["-c"],{}),(["a.txt"],{"a.txt":text}),(["-c","a.txt"],{"a.txt":text}),
 (["a.txt","stdout"],{"a.txt":text}),(["a.txt","-"],{"a.txt":text}),
