import struct
def u32(b,i):return struct.unpack_from('<I',b,i)[0]
def hf(v):return ((v*2654435761)&0xffffffff)>>(32-15)
class M:
 def __init__(self,src):
  self.src=src;self.head=[-1]*(1<<15);self.prev=[-1]*len(src);self.up=0;self.n=len(src)
 def insert_upto(self,pos):
  while self.up<pos:
   p=self.up
   if p+4<=self.n:
    h=hf(u32(self.src,p));self.prev[p]=self.head[h];self.head[h]=p
   self.up+=1
 def find(self,pos,maxsearch=4096):
  if pos+4>self.n:return (0,0)
  self.insert_upto(pos)
  h=hf(u32(self.src,pos));cand=self.head[h];best=0;bestoff=0;maxf=self.n-5-pos;s=0
  while cand>=0 and pos-cand<=65535 and s<maxsearch:
   s+=1
   if u32(self.src,cand)==u32(self.src,pos):
    l=4
    while l<maxf and self.src[pos+l]==self.src[cand+l]:l+=1
    if l>best:best=l;bestoff=pos-cand
    if best>=maxf:break
   cand=self.prev[cand]
  return best,bestoff

def hc(src,maxsearch=4096,lookahead=1,la_condition='gt'):
 n=len(src);m=M(src);seqs=[];anchor=0;ip=0;matchLimit=n-12
 while ip<=matchLimit:
  length,offset=m.find(ip,maxsearch)
  if length<4:ip+=1;continue
  # lookahead
  skipped=False
  for d in range(1,lookahead+1):
   if ip+d>matchLimit:break
   nl,_=m.find(ip+d,maxsearch)
   cond = (nl>length) if la_condition=='gt' else (nl>length+d if la_condition=='gain' else nl>=length)
   if cond:
    ip+=d;skipped=True;break
  if skipped:continue
  cand=ip-offset
  while ip>anchor and cand>0 and src[ip-1]==src[cand-1]:
   ip-=1;cand-=1;length+=1;offset=ip-cand
  lastRun=n-5
  if ip+length>lastRun:length=lastRun-ip
  seqs.append((ip-anchor,offset,length));anchor=ip+length;ip=anchor
 seqs.append((n-anchor,0,0));return seqs
